window.CURRICULUM = [{"id":"village","index":1,"name":"Reema's Village","subtitle":"Where the question began","emoji":"🏡","theme":"Warm sunset, old books, floating scrolls","palette":{"from":"#f7b267","to":"#e76f51","accent":"#7a3b1d"},"lessons":[{"id":"v1","title":"The Falling Paper","icon":"📜","kind":"lesson","story":"Whoosh! A paper slips out of Reema's old book, covered in strange wedge-shaped marks. Her father smiles: 'Those were numbers, 4000 years ago.'","teach":[{"title":"Mesopotamia","body":"Around 4000 years ago a civilisation flourished in Mesopotamia, in western Asia — most of today's Iraq and nearby lands. Those strange symbols were their numbers.","visual":"𒐕 𒌋 𒐕𒐕"},{"title":"Numbers have a story","body":"The idea of a number, and of writing numbers, changed across time and across geographies before reaching the form we use today.","visual":"🏺 → 🏛 → 🔢"}],"questions":[{"kind":"mcq","prompt":"The symbols on Reema's paper came from which ancient region?","options":["Mesopotamia","Antarctica","Australia","Japan"],"answer":0,"explain":"Mesopotamia lay in western Asia, covering much of present-day Iraq."},{"kind":"numberline","prompt":"About how many years ago did Mesopotamia's civilisation flourish? Tap the number line.","min":0,"max":6000,"step":500,"answer":4000,"explain":"The chapter says the Mesopotamian civilisation flourished around 4000 years ago."},{"kind":"fill","prompt":"Mesopotamia covered a major part of present-day ______.","answer":"iraq","placeholder":"country name","explain":"Mesopotamia covered a major part of present-day Iraq and a few neighbouring countries."}]},{"id":"v2","title":"Why Humans Counted","icon":"🐄","kind":"lesson","story":"Travel back to the Stone Age. No digits, no writing — but people still had to keep track of food, animals and days.","teach":[{"title":"Reasons to count","body":"Even in the Stone Age humans counted: quantity of food, animals in the livestock, trade of goods, offerings in rituals, and passing days.","visual":"🍖 🐑 🤝 🌕"},{"title":"Tracking the sky","body":"They wanted to predict the new moon, the full moon and the onset of a season — so days had to be tracked.","visual":"🌑 🌓 🌕"}],"questions":[{"kind":"mcq","prompt":"Which was NOT a Stone Age reason for counting given in the chapter?","options":["Counting livestock","Trading goods","Sending emails","Tracking passing days"],"answer":2,"explain":"Food, livestock, trade, ritual offerings and days — those were the reasons."},{"kind":"match","prompt":"Match each need to what it helped with.","pairs":[["Counting cows","Livestock"],["Counting days","New moon & seasons"],["Counting goods","Trade"]],"explain":"Each counting need solved a real everyday problem."},{"kind":"mcq","prompt":"When Stone Age people said or wrote numbers, they used…","options":["The digits 0–9 we use today","Their own, different systems","Calculators","Nothing at all"],"answer":1,"explain":"They did not use the numbers we use today; many different systems existed."}]},{"id":"v3","title":"Catch the Symbols","icon":"✨","kind":"minigame","story":"The Number Thief scattered symbols into the wind. Tap only the true statements to catch them!","teach":[{"title":"Reminder","body":"Numbers came from many peoples: sticks, pebbles, body parts, names, and written symbols.","visual":"🪵 🪨 ✋ 🔤"}],"questions":[{"kind":"tap","prompt":"Tap the symbol set that is NOT a way ancient people represented numbers.","options":["🪵 sticks","🪨 pebbles","✋ body parts","📱 phones"],"answer":3,"explain":"History shows number systems made of objects, names and written symbols — not phones!"},{"kind":"mcq","prompt":"Reema's father explained that number representation reached its modern form…","options":["Suddenly, in one country, in one year","Gradually, over time and across geographies","Only in Europe","Only after computers"],"answer":1,"explain":"The idea evolved over the course of time, across geographies."}]},{"id":"v-boss","title":"The Thief's First Riddle","icon":"👹","kind":"boss","boss":{"name":"Shadow of Doubt","taunt":"Without numbers, your village forgets how many cows it owns!"},"story":"A shadow rises from the scrolls. Answer correctly to drive it out of the village.","teach":[],"questions":[{"kind":"mcq","prompt":"Where did the structure of our modern oral and written numbers originate?","options":["Greece","India","Egypt","Rome"],"answer":1,"explain":"It originated in India thousands of years ago."},{"kind":"mcq","prompt":"Which ancient Indian text listed number names based on powers of 10?","options":["Yajurveda Samhita","Bakhshali manuscript","Āryabhaṭīya","Brāhmasphuṭasiddhānta"],"answer":0,"explain":"The Yajurveda Samhita listed eka, dasha, shata, sahasra, ayuta… up to 10¹² and beyond."},{"kind":"order","prompt":"Arrange these Sanskrit number names from smallest to largest.","items":["sahasra (1000)","eka (1)","shata (100)","dasha (10)"],"answer":["eka (1)","dasha (10)","shata (100)","sahasra (1000)"],"explain":"eka, dasha, shata, sahasra — each ten times the one before."}]}]},{"id":"forest","index":2,"name":"Forest of Counting","subtitle":"One stick for every cow","emoji":"🌳","theme":"Huge trees, animals, pebbles, wooden bridges","palette":{"from":"#63b995","to":"#2d6a4f","accent":"#14452f"},"lessons":[{"id":"f1","title":"One-to-One Mapping","icon":"🪵","kind":"lesson","story":"The herd returns at dusk. Without numbers, how do you know none is missing? Keep one stick per cow.","teach":[{"title":"Method 1 — objects","body":"For every cow, keep one stick. Associating each cow with exactly one stick, so no two cows share a stick, is called one-to-one mapping.","visual":"🐄🐄🐄  ↔  | | |"},{"title":"Comparing herds","body":"Pair your sticks with your neighbour's sticks. Whoever has sticks left over has more cows — and the leftovers tell you how many more you need.","visual":"| | | | vs | | |"}],"questions":[{"kind":"fill","prompt":"Associating each cow with exactly one stick is called a ______ mapping.","answer":"one-to-one","placeholder":"type the term","explain":"One-to-one mapping: no two cows map to the same stick."},{"kind":"tally","prompt":"7 cows came back from grazing. Place one stick for each cow.","count":7,"explain":"One stick per cow — the collection of sticks is the number of cows."},{"kind":"mcq","prompt":"You pair your sticks with your neighbour's and 3 of yours are left over. This means…","options":["You have 3 fewer cows","You have 3 more cows","Herds are equal","Nothing can be said"],"answer":1,"explain":"Leftover sticks after pairing show how many more you have."}]},{"id":"f2","title":"Counting with Sounds","icon":"🔤","kind":"lesson","story":"Instead of carrying sticks, use a fixed sequence of sounds — a, b, c… Each object gets the next name.","teach":[{"title":"Method 2 — names","body":"Use a standard sequence of sounds or names in a fixed order. Map each object to the next letter: 1→a, 2→b, 3→c … 26→z.","visual":"a b c d … z"},{"title":"The limitation","body":"With only 26 letters you cannot count a collection of more than 26 objects. The sequence must never end.","visual":"z → ??"}],"questions":[{"kind":"mcq","prompt":"Using English letters a–z as numbers, the largest collection you can count is…","options":["10","24","26","unlimited"],"answer":2,"explain":"The alphabet ends at z, so only 26 objects can be counted."},{"kind":"mcq","prompt":"In this system, which letter represents 5?","options":["d","e","f","g"],"answer":1,"explain":"1→a, 2→b, 3→c, 4→d, 5→e."},{"kind":"mcq","prompt":"One way to extend the letter system is to…","options":["Stop counting at 26","Use strings of more than one letter, e.g. 'aa' for 27","Use Roman numerals instead","Use pebbles"],"answer":1,"explain":"The chapter suggests strings such as 'aa' for 27 — there are many ways."},{"kind":"numberline","prompt":"Using English letters a–z as numbers, what's the largest single-letter collection you can count? Tap it on the number line.","min":0,"max":30,"step":1,"answer":26,"explain":"There are 26 letters, so the largest single-letter count is 26 — before extending to two-letter strings like 'aa'."}]},{"id":"f3","title":"Written Symbols Appear","icon":"✒️","kind":"lesson","story":"Method 3: draw the sequence instead of carrying or saying it. I, II, III, IV, V…","teach":[{"title":"A number system","body":"A standard sequence of objects, names or written symbols in a fixed order is called a number system. Counting = one-to-one mapping onto that sequence, in order.","visual":"I II III IV V VI"},{"title":"Numerals","body":"The symbols occurring in a written number system are called numerals. 0, 1, 5, 36, 193 are numerals of the Hindu number system.","visual":"0 1 5 36 193"}],"questions":[{"kind":"tap","prompt":"Tap the symbol that stands for 9 in Method 3 (the Roman system).","options":["VI","IX","XI","IV"],"answer":1,"explain":"9 is written IX — one less than ten."},{"kind":"order","prompt":"Arrange these numerals in increasing order.","items":["XV","IV","XX","IX"],"answer":["IV","IX","XV","XX"],"explain":"4, 9, 15, 20."},{"kind":"fill","prompt":"The symbols of a written number system are called ______.","answer":"numerals","explain":"Numerals are the written symbols; the number system is the ordered sequence."}]},{"id":"f-boss","title":"Bridge Guardian","icon":"🐗","kind":"boss","boss":{"name":"Bridge Guardian","taunt":"No crossing until you prove you can count without digits!"},"story":"A wooden bridge, a stubborn guardian, and three tests of counting.","teach":[],"questions":[{"kind":"tally","prompt":"Count the birds: place a stick for each of the 12 birds.","count":12,"explain":"Sticks give an unending sequence — but 12 sticks is already clumsy!"},{"kind":"mcq","prompt":"Why is the stick system inconvenient for large collections?","options":["Sticks break easily","You need as many sticks as objects","It has no order","It stops at 26"],"answer":1,"explain":"It is unending, but you need as many sticks as objects counted."},{"kind":"mcq","prompt":"Which system was used in Europe before the Hindu number system?","options":["Mayan","Roman","Chinese rod","Egyptian"],"answer":1,"explain":"Method 3 is the Roman number system, widely used in Europe for centuries."}]}]},{"id":"cave","index":3,"name":"Cave of Ancient Humans","subtitle":"Notches that outlived empires","emoji":"🦴","theme":"Stone caves, fire, bones, rock paintings","palette":{"from":"#c98b5e","to":"#6b4226","accent":"#3b2417"},"lessons":[{"id":"c1","title":"Tally Marks","icon":"𝍸","kind":"lesson","story":"Firelight flickers on the cave wall. Someone here cut one notch for every animal that passed.","teach":[{"title":"Notches","body":"One of the oldest methods of number representation is making notches — marks cut on a bone or a cave wall. These are tally marks.","visual":"| | | | |"},{"title":"Same idea as sticks","body":"A mark is made for each object counted, so the collection of marks is the total. It matches Method 1, except a mark replaces a stick.","visual":"🪵 ≡ 𝍸"}],"questions":[{"kind":"tally","prompt":"Carve tally marks for the 9 animals that passed the cave.","count":9,"explain":"One notch per animal — the marks themselves are the number."},{"kind":"mcq","prompt":"Tally marks are most similar to which counting method?","options":["Using sticks","Using letters","Using place value","Using zero"],"answer":0,"explain":"It's the same one-to-one idea; only a mark replaces the stick."}]},{"id":"c2","title":"Bones of Ishango & Lebombo","icon":"🦴","kind":"lesson","story":"Archaeologists dug up bones older than every city on Earth — and they were covered in notches.","teach":[{"title":"Ishango bone","body":"Dating back 20,000 to 35,000 years, discovered in the Democratic Republic of Congo. Its notches are arranged in columns, possibly indicating calendrical systems.","visual":"🦴 ||| ||||| |||"},{"title":"Lebombo bone","body":"Discovered in South Africa, around 44,000 years old, with 29 notches. One of the oldest mathematical artefacts — perhaps a tally stick or lunar calendar.","visual":"29 notches 🌙"}],"questions":[{"kind":"match","prompt":"Match each bone to its discovery place.","pairs":[["Ishango bone","DR Congo"],["Lebombo bone","South Africa"]],"explain":"Ishango — DR Congo. Lebombo — South Africa."},{"kind":"mcq","prompt":"How many notches does the Lebombo bone carry?","options":["12","20","29","44"],"answer":2,"explain":"29 notches — possibly a lunar calendar."},{"kind":"mcq","prompt":"Which bone is older?","options":["Ishango","Lebombo","Both same age","Neither is old"],"answer":1,"explain":"Lebombo is about 44,000 years old; Ishango is 20,000–35,000 years old."},{"kind":"numberline","prompt":"Tap how many thousand years ago these tally-marked bones were found to date back to.","min":0,"max":50,"step":5,"answer":20,"explain":"Archaeologists found bones older than 20,000 years bearing tally marks."}]},{"id":"c-boss","title":"The Stone Giant","icon":"🗿","kind":"boss","boss":{"name":"Stone Giant","taunt":"My notches are broken. Repair them, little Guardian."},"story":"The giant's bone is cracked. Restore the correct notch counts to wake the cave's memory.","teach":[],"questions":[{"kind":"tally","prompt":"Repair the Lebombo bone: carve its full number of notches.","count":29,"explain":"The Lebombo bone has 29 notches."},{"kind":"mcq","prompt":"Ishango's notches are arranged in columns, which may indicate…","options":["Prices","Calendrical systems","Names","Music"],"answer":1,"explain":"The columns possibly indicate calendrical systems."},{"kind":"mcq","prompt":"Tally marks have a drawback. Which one?","options":["They cannot show one-to-one mapping","Large numbers need huge numbers of marks","They need zero","They only reach 26"],"answer":1,"explain":"Like sticks, tally counting becomes cumbersome for large collections."}]}]},{"id":"tribal","index":4,"name":"Tribal Lands","subtitle":"Bodies, twos and names","emoji":"🌍","theme":"Villages, totems, nature","palette":{"from":"#f4a261","to":"#a4633a","accent":"#5c3520"},"lessons":[{"id":"t1","title":"Counting on the Body","icon":"✋","kind":"lesson","story":"In Papua New Guinea, the counting sequence is written on the body itself: fingers, wrist, elbow, shoulder, ear…","teach":[{"title":"Body parts as a number system","body":"Many groups across the world used hands and body parts for counting. A group in Papua New Guinea still uses a fixed order of body points as their standard sequence.","visual":"👆 ✋ 💪 👂 👃"},{"title":"Why it works","body":"Any standard sequence with a fixed order can serve as a number system — as long as everyone agrees on the order.","visual":"fixed order = countable"}],"questions":[{"kind":"mcq","prompt":"The body-part counting system described comes from…","options":["Papua New Guinea","Peru","Portugal","Poland"],"answer":0,"explain":"A group of people in Papua New Guinea used and still use body parts to count."},{"kind":"mcq","prompt":"What must a body-part sequence have to work as a number system?","options":["Bright colours","A fixed order","Exactly ten points","A zero"],"answer":1,"explain":"A number system is a standard sequence with a fixed order."}]},{"id":"t2","title":"Gumulgal: Counting in Twos","icon":"👣","kind":"lesson","story":"The Gumulgal of Australia built number names out of just two words: urapon and ukasar.","teach":[{"title":"The names","body":"1 urapon, 2 ukasar, 3 ukasar-urapon, 4 ukasar-ukasar, 5 ukasar-ukasar-urapon, 6 ukasar-ukasar-ukasar. Anything greater than 6 was called ras.","visual":"3 = 2+1 · 4 = 2+2 · 5 = 2+2+1"},{"title":"A big idea","body":"Counting in groups of a fixed size (here 2) is more efficient than a tally. Common group sizes in history: 2, 5, 10 and 20.","visual":"2 · 5 · 10 · 20"},{"title":"A puzzle of history","body":"The Bakairi of South America and the Bushmen of South Africa developed equivalent systems far away, with no trace of contact. Perhaps they shared common ancestors.","visual":"🌏 ↔ 🌍 ↔ 🌎"}],"questions":[{"kind":"build","prompt":"Build the Gumulgal name for 5 (tap the words in order).","tokens":["ukasar","urapon"],"answer":"ukasar-ukasar-urapon","explain":"5 = 2 + 2 + 1 → ukasar-ukasar-urapon."},{"kind":"mcq","prompt":"What did the Gumulgal call any number greater than 6?","options":["urapon","ukasar","ras","dasha"],"answer":2,"explain":"Numbers greater than 6 were simply called ras."},{"kind":"match","prompt":"Match the Gumulgal name with its value.","pairs":[["urapon","1"],["ukasar","2"],["ukasar-urapon","3"],["ukasar-ukasar","4"]],"explain":"Names are built by adding 2s and a final 1 if needed."},{"kind":"mcq","prompt":"Most humans can see the size of a collection at a glance only up to about…","options":["4 objects","10 objects","20 objects","60 objects"],"answer":0,"explain":"Most people find it difficult to see groups of 5 or more at a single glance."},{"kind":"numberline","prompt":"Most humans can see the size of a collection at a glance only up to about how many objects? Tap it on the number line.","min":0,"max":10,"step":1,"answer":4,"explain":"Beyond about 4 objects, most people can no longer 'see' the total at a glance and must count instead."}]},{"id":"t-boss","title":"The Ancient Spirit","icon":"🌀","kind":"boss","boss":{"name":"Ancient Spirit","taunt":"Three peoples, one system. Explain the mystery!"},"story":"A totem glows. The spirit inside tests your understanding of counting in groups.","teach":[],"questions":[{"kind":"build","prompt":"Build the Gumulgal name for 6.","tokens":["ukasar","urapon"],"answer":"ukasar-ukasar-ukasar","explain":"6 = 2 + 2 + 2 → ukasar-ukasar-ukasar."},{"kind":"mcq","prompt":"One theory for why three distant peoples share this system is…","options":["They traded by sea","They may have had common ancestors who migrated","They copied Rome","Coincidence of language"],"answer":1,"explain":"One theory: common ancestors used it, and descendants migrated far apart."},{"kind":"mcq","prompt":"Counting in groups of 5 can be seen in which system?","options":["Roman","Gumulgal","Lebombo","Bakairi"],"answer":0,"explain":"The Roman system uses V for a group of five."}]}]},{"id":"rome","index":5,"name":"Roman Empire","subtitle":"Landmark numbers carved in marble","emoji":"🏛","theme":"Marble pillars, golden temples, statues","palette":{"from":"#e9d8a6","to":"#bb9457","accent":"#6b4d1f"},"lessons":[{"id":"r1","title":"I, V, X and Beyond","icon":"🔱","kind":"lesson","story":"Marble everywhere, and every temple stamped with letters that are secretly numbers.","teach":[{"title":"Landmark numbers","body":"Numbers given a new basic symbol are called landmark numbers. Roman landmarks: I=1, V=5, X=10, L=50, C=100, D=500, M=1000.","visual":"I V X L C D M"},{"title":"How to write a number","body":"Group into as many of the largest landmark as possible, then the next, and so on. 27 = 10+10+5+1+1 → XXVII.","visual":"27 → XXVII"},{"title":"Subtractive forms","body":"4 is one less than 5 → IV. So 40 is ten less than fifty → XL. People were not always consistent: 40 was sometimes XXXX.","visual":"IV · IX · XL"}],"questions":[{"kind":"match","prompt":"Match each Roman symbol with its value.","pairs":[["L","50"],["C","100"],["D","500"],["M","1000"]],"explain":"L=50, C=100, D=500, M=1000."},{"kind":"build","prompt":"Build the Roman numeral for 302.","tokens":["M","D","C","L","X","V","I"],"answer":"CCCII","explain":"302 = 100+100+100+1+1 → CCCII."},{"kind":"fill","prompt":"Write 715 in Roman numerals.","answer":"dccxv","placeholder":"e.g. XXVII","explain":"715 = 500+100+100+10+5 → DCCXV."},{"kind":"numberline","prompt":"What decimal value does the Roman numeral X represent? Tap it on the number line.","min":0,"max":20,"step":1,"answer":10,"explain":"X is one of the seven Roman landmark numbers, worth 10."}]},{"id":"r2","title":"Adding Like a Roman","icon":"➕","kind":"lesson","story":"The forum's merchants add without ever writing a digit. Group the letters, then trade up.","teach":[{"title":"Group and trade up","body":"Add CCXXXII + CCCCXIII by counting all Is, Xs and Cs, then regrouping: 5 Cs make a D. The sum is DCXLV.","visual":"CCXXXII + CCCCXIII = DCXLV"},{"title":"The weakness","body":"Roman numerals do not lend themselves to easy arithmetic, especially multiplication and division, because each landmark groups by a different size.","visual":"V×L = ? 😖"},{"title":"The abacus","body":"Romans used a calculating tool called the abacus for arithmetic — but only specially trained people could use it.","visual":"🧮"}],"questions":[{"kind":"fill","prompt":"LXXXVII + LXXVIII = ? (write in Roman numerals)","answer":"clxv","placeholder":"Roman numeral","explain":"87 + 78 = 165 = 100+50+10+5 → CLXV."},{"kind":"mcq","prompt":"What is V × L?","options":["CC","CCL","D","L"],"answer":1,"explain":"5 × 50 = 250 → CCL."},{"kind":"mcq","prompt":"Why is multiplication hard in the Roman system?","options":["Landmark numbers are not powers of one number","There is no symbol for 1","It has a zero","It uses place value"],"answer":0,"explain":"Products of landmarks are not landmarks, so multiplication gets messy."}]},{"id":"r-boss","title":"The Roman General","icon":"⚔️","kind":"boss","boss":{"name":"Roman General","taunt":"Convert my legions' numbers, or the treasure stays sealed!"},"story":"The general blocks the treasury. Each correct conversion loosens a lock.","teach":[],"questions":[{"kind":"fill","prompt":"Represent 1222 in the Roman system.","answer":"mccxxii","placeholder":"Roman numeral","explain":"1222 = 1000+100+100+10+10+1+1 → MCCXXII."},{"kind":"fill","prompt":"Represent 2999 in the Roman system.","answer":"mmcmxcix","placeholder":"Roman numeral","explain":"2999 = MM + CM (900) + XC (90) + IX (9) → MMCMXCIX."},{"kind":"mcq","prompt":"What is VII × IX?","options":["LXIII","LXVI","XVI","XLIX"],"answer":0,"explain":"7 × 9 = 63 = 50+10+1+1+1 → LXIII."},{"kind":"order","prompt":"Arrange the landmark numbers from smallest to largest.","items":["C","I","M","X","D","V","L"],"answer":["I","V","X","L","C","D","M"],"explain":"1, 5, 10, 50, 100, 500, 1000."}]}]},{"id":"egypt","index":6,"name":"Egyptian Desert","subtitle":"Powers of ten in the sand","emoji":"🏜","theme":"Pyramids, golden sand, camels, hieroglyphics","palette":{"from":"#ffd166","to":"#c98f2b","accent":"#7a5310"},"lessons":[{"id":"e1","title":"The Egyptian System","icon":"𓂀","kind":"lesson","story":"Around 3000 BCE, scribes in Egypt found a rhythm: every new symbol is ten of the last.","teach":[{"title":"Ten of the previous","body":"Start with 1. Group ten of them → 10. Group ten tens → 100. Each landmark is 10 times the previous, so all are powers of 10: 1, 10, 10², 10³ … 10⁷.","visual":"| ∩ 𓍢 𓍟 𓆼 𓂭 𓁨"},{"title":"Writing a number","body":"Repeat symbols as needed, starting from the largest landmark below the number. 324 = 100+100+100+10+10+4.","visual":"324 → 𓍢𓍢𓍢 ∩∩ ||||"}],"questions":[{"kind":"build","prompt":"Build 1023 in Egyptian numerals (tap symbols; | = 1, ∩ = 10, 𓍢 = 100, 𓍟 = 1000).","tokens":["𓍟","𓍢","∩","|"],"answer":"𓍟∩∩|||","explain":"1023 = 1000 + 10 + 10 + 1 + 1 + 1."},{"kind":"mcq","prompt":"What number is 𓍢𓍢 ∩∩∩ ||||?","options":["234","2034","324","204"],"answer":0,"explain":"100+100 + 10+10+10 + 4 = 234."},{"kind":"mcq","prompt":"Can any Egyptian symbol appear 10 or more times in a numeral?","options":["Yes, as often as needed","No — ten of them are replaced by the next landmark","Only the symbol for 1","Only the symbol for 1000"],"answer":1,"explain":"Ten of a landmark always regroup into the next landmark."}]},{"id":"e2","title":"Arithmetic in the Sand","icon":"🧮","kind":"lesson","story":"The scribe adds two numerals by sweeping symbols together — then trading tens.","teach":[{"title":"Adding","body":"Collect all symbols of each kind. Every 10 |s become one ∩; every 10 ∩s become the next landmark. Same trade every time — that's the power of a base.","visual":"10| → ∩   10∩ → 𓍢"},{"title":"Multiplying","body":"Each landmark is a power of 10, so multiplying two landmarks gives another landmark. ∩ × 𓍢 = 𓍟. This is why base systems make multiplication easy.","visual":"10 × 100 = 1000"}],"questions":[{"kind":"mcq","prompt":"In the Egyptian system, what is ∩ × 𓍢 (10 × 100)?","options":["𓍢 (100)","𓍟 (1000)","𓆼 (10,000)","∩ (10)"],"answer":1,"explain":"Multiplying by 10 raises the power by one: 10 × 100 = 1000."},{"kind":"mcq","prompt":"The product of any two landmark numbers in a base system is…","options":["Never a landmark","Always another landmark","Sometimes zero","Always 10"],"answer":1,"explain":"Powers of n multiply to give powers of n — another landmark."},{"kind":"mcq","prompt":"What is the shortcoming of the Egyptian system?","options":["It cannot show 1","Bigger numbers need endless new symbols for higher powers of 10","It has no base","It cannot be added"],"answer":1,"explain":"Larger numbers would need an unending sequence of new symbols."}]},{"id":"e-boss","title":"The Pharaoh","icon":"👑","kind":"boss","boss":{"name":"Pharaoh of Sand","taunt":"Decode my tomb, Guardian, or stay inside it."},"story":"Hieroglyphs shimmer on the tomb wall. Decode them to open the pyramid.","teach":[],"questions":[{"kind":"mcq","prompt":"70707 = 70000 + 700 + 7. How many 𓆼 (10,000) symbols does it need?","options":["7","70","0","707"],"answer":0,"explain":"70000 = 7 × 10,000, so seven 𓆼 symbols."},{"kind":"build","prompt":"Build 2660 in Egyptian numerals.","tokens":["𓍟","𓍢","∩","|"],"answer":"𓍟𓍟𓍢𓍢𓍢𓍢𓍢𓍢∩∩∩∩∩∩","explain":"2660 = 2×1000 + 6×100 + 6×10."},{"kind":"mcq","prompt":"The Egyptian system is a base-___ system.","options":["5","10","20","60"],"answer":1,"explain":"Its landmarks are powers of 10 — a base-10 or decimal system."},{"kind":"numberline","prompt":"70707 = 70000 + 700 + 7. How many 𓆼 (10,000) symbols does it need? Tap it on the number line.","min":0,"max":10,"step":1,"answer":7,"explain":"70000 = 7×10,000, so exactly seven 𓆼 symbols are needed."}]}]},{"id":"volcano","index":7,"name":"Base Number Volcano","subtitle":"Choose your own base","emoji":"🌋","theme":"Lava, floating rocks, magic crystals","palette":{"from":"#ff7b54","to":"#9d0208","accent":"#4a0303"},"lessons":[{"id":"b1","title":"Inventing Base-5","icon":"🔺","kind":"lesson","story":"Crystals float above the lava in groups of five. Build a whole number system out of them.","teach":[{"title":"The recipe","body":"First landmark is 1. Group 5 of the previous landmark to get the next: 1, 5, 25, 125, 625, 3125 — all powers of 5.","visual":"△=1 □=5 ⬡=25 ○=125"},{"title":"Definition of base-n","body":"A system where (a) the first landmark is 1 and (b) each next landmark is the current one times a fixed number n is a base-n number system. Base-10 is also called decimal.","visual":"1, n, n², n³ …"},{"title":"Example","body":"143 = 125 + 5 + 5 + 5 + 1 + 1 + 1 → ○□□□△△△","visual":"143 → ○□□□△△△"}],"questions":[{"kind":"build","prompt":"Write 15 in our base-5 system (△=1, □=5, ⬡=25, ○=125).","tokens":["○","⬡","□","△"],"answer":"□□□","explain":"15 = 5 + 5 + 5 → □□□."},{"kind":"build","prompt":"Write 50 in the base-5 system.","tokens":["○","⬡","□","△"],"answer":"⬡⬡","explain":"50 = 25 + 25 → ⬡⬡."},{"kind":"mcq","prompt":"Is there a number that cannot be represented in the base-5 system?","options":["Yes, numbers above 3125","No — powers of 5 grow without end","Yes, zero","Yes, odd numbers"],"answer":1,"explain":"The landmarks 1, 5, 25, 125… never stop, so every number can be built."}]},{"id":"b2","title":"Any Base You Like","icon":"⚡","kind":"lesson","story":"The volcano's power tower asks: what if the group size were 7? Or 4? Or 2?","teach":[{"title":"Landmarks of base-n","body":"They are the powers of n starting from n⁰ = 1: 1, n, n², n³ … For base-7: 1, 7, 49, 343, 2401.","visual":"7⁰ 7¹ 7² 7³"},{"title":"Why a base wins","body":"Grouping is always by the same size, so adding means simple trading up; and products of landmarks are landmarks, so multiplying is simple too.","visual":"same trade every time"}],"questions":[{"kind":"order","prompt":"Arrange the landmark numbers of a base-7 system in increasing order.","items":["49","1","343","7"],"answer":["1","7","49","343"],"explain":"1, 7, 7²=49, 7³=343."},{"kind":"numberline","prompt":"In base-8, 25 = (3) × 8 + (?) × 1. What is the missing digit? Tap it on the number line.","answer":1,"explain":"25 = 3×8 + 1, so 25 is written 31 in base-8.","min":0,"max":8,"step":1},{"kind":"mcq","prompt":"A simple rule to multiply a number by 5 in the base-5 system is…","options":["Replace every symbol by the next landmark's symbol","Add five more symbols","Remove one symbol","Nothing changes"],"answer":0,"explain":"Multiplying by the base shifts each landmark up by one."}]},{"id":"b-boss","title":"Magma Machine","icon":"🔥","kind":"boss","boss":{"name":"Magma Machine","taunt":"Feed me bases, or I flood the path with lava!"},"story":"A machine of glowing gears demands numbers in different bases.","teach":[],"questions":[{"kind":"build","prompt":"Write 137 in the base-5 system (△=1, □=5, ⬡=25, ○=125).","tokens":["○","⬡","□","△"],"answer":"○□□△△","explain":"137 = 125 + 5 + 5 + 1 + 1."},{"kind":"mcq","prompt":"What is 25 (base-10) written in base-5?","options":["100","50","25","11"],"answer":0,"explain":"25 = 1×5² + 0×5 + 0 → 100 in base-5."},{"kind":"mcq","prompt":"Which is the correct definition of base-n?","options":["First landmark is n and the rest are multiples of n","First landmark is 1 and each next is the current one × n","Landmarks are any convenient numbers","Landmarks are 1, 5, 10, 50, 100"],"answer":1,"explain":"First landmark 1, then multiply by the fixed number n each time."}]}]},{"id":"babylon","index":8,"name":"Babylon Space Temple","subtitle":"Sixty, and the first place value","emoji":"🌌","theme":"Mesopotamia, stars, night sky, constellations","palette":{"from":"#5f6caf","to":"#22223b","accent":"#0f0f1f"},"lessons":[{"id":"m1","title":"The Sexagesimal System","icon":"🕰","kind":"lesson","story":"High in the ziggurat, priests count the stars in sixties — and time still obeys them.","teach":[{"title":"Base-60","body":"The later Mesopotamian system became a base-60 or sexagesimal system, also called the Babylonian number system. It used ⊻ for 1 and ˂ for 10.","visual":"⊻ = 1   ˂ = 10"},{"title":"Why 60?","body":"Theories include links with the 30-day lunar month, the Sun's apparent revolution, the ease of fractions, and their earlier landmarks 1, 10, 60, 600, 3600 reducing to powers of 60.","visual":"1 · 60 · 3600 · 216000"},{"title":"It still lives","body":"1 hour = 60 minutes, 1 minute = 60 seconds — the Babylonian base is on every clock.","visual":"⏱ 60 · 60"}],"questions":[{"kind":"mcq","prompt":"The Babylonian base-60 system is also called…","options":["Decimal","Sexagesimal","Vigesimal","Binary"],"answer":1,"explain":"Base-60 = sexagesimal."},{"kind":"match","prompt":"Match the symbol to its value.","pairs":[["⊻","1"],["˂","10"]],"explain":"⊻ for one, ˂ for ten."},{"kind":"mcq","prompt":"Where do we still see base-60 today?","options":["Money","Time: 60 minutes, 60 seconds","Distance","Weight"],"answer":1,"explain":"Our units of time preserve the sexagesimal system."}]},{"id":"m2","title":"Place Value Is Born","icon":"🪐","kind":"lesson","story":"Drop the landmark symbols. Let the position of a symbol tell you its power of 60.","teach":[{"title":"Compact writing","body":"640 = (10)×60 + 40. Instead of writing the landmark symbols, just write '10' then '40' — the rightmost group counts 1s, the next 60s, the next 3600s.","visual":"640 → ˂ | ˂˂˂˂"},{"title":"Regrouping","body":"No power of 60 may occur 60 or more times: 60 of them form the next power. (1)×3600 + (70)×60 + 2 = (2)×3600 + (10)×60 + 2.","visual":"70 sixties → 1 more 3600"},{"title":"Place value system","body":"A number system with a base that uses the position of a symbol to decide its landmark number is a positional or place value system.","visual":"position = power"},{"title":"The missing piece","body":"Blank spaces marked empty positions and caused confusion. Later Mesopotamians added a placeholder symbol — like our 0 — though they mostly used it in the middle, not at the end.","visual":"◻ = placeholder"}],"questions":[{"kind":"mcq","prompt":"7530 = (2)×3600 + (5)×60 + 30. Which digit sits in the 60s place?","options":["2","5","30","60"],"answer":1,"explain":"There are five 60s in 7530."},{"kind":"numberline","prompt":"63 = (1) × 60 + (?) × 1. What is the missing number? Tap it on the number line.","answer":3,"explain":"63 = 60 + 3.","min":0,"max":10,"step":1},{"kind":"numeric","prompt":"3605 = (1) × 3600 + (?) × 1.","answer":5,"explain":"3605 = 1×3600 + 0×60 + 5 — and the empty 60s place needs a placeholder!"},{"kind":"mcq","prompt":"Why did the Mesopotamian system stay ambiguous?","options":["Blank spaces were inconsistent and the placeholder was not used at the end","It had too many digits","It had no base","It could not show 1"],"answer":0,"explain":"Uneven spacing and a placeholder missing at the end left numerals ambiguous."}]},{"id":"m-boss","title":"The Babylonian King","icon":"🗼","kind":"boss","boss":{"name":"Babylonian King","taunt":"Read my tablets correctly, or the stars go dark!"},"story":"Clay tablets orbit the temple. Read each one to light a constellation.","teach":[],"questions":[{"kind":"numeric","prompt":"132 = (2) × 60 + (?) × 1.","answer":12,"explain":"132 = 120 + 12."},{"kind":"numeric","prompt":"200 = (3) × 60 + (?) × 1.","answer":20,"explain":"200 = 180 + 20."},{"kind":"mcq","prompt":"A placeholder symbol is indispensable because…","options":["It makes numbers look nice","It shows an empty position unambiguously","It is the largest digit","It replaces the base"],"answer":1,"explain":"Zero as a placeholder shows nothingness in a position, removing ambiguity."}]}]},{"id":"maya","index":9,"name":"Mayan Jungle","subtitle":"Shells, dots and bars","emoji":"🌿","theme":"Temples, rainforest, waterfalls, ruins","palette":{"from":"#52b788","to":"#1b4332","accent":"#08281a"},"lessons":[{"id":"y1","title":"Dots, Bars and a Shell","icon":"🐚","kind":"lesson","story":"Deep in the rainforest, carvings stack upwards — and a seashell means nothing at all.","teach":[{"title":"Symbols","body":"A dot • is 1, a bar — is 5, and a shell stands for zero. Dots and bars write the numbers 1 to 19.","visual":"• = 1   — = 5   🐚 = 0"},{"title":"Almost base-20","body":"Landmark numbers: 1, 20, 20×18 = 360, 20²×18 = 7200, 20³×18 = 144000. Because the third landmark is 360 and not 400, it is not a true base-20 system.","visual":"1 · 20 · 360 · 7200"},{"title":"Written vertically","body":"The lowest group counts 1s, the group above counts 20s, above that 360s. Example: 4 over 11 over 0 = 4×360 + 11×20 + 0 = 1660.","visual":"4 / 11 / 🐚 = 1660"}],"questions":[{"kind":"match","prompt":"Match the Mayan symbol with its value.","pairs":[["•","1"],["—","5"],["🐚","0"]],"explain":"Dot 1, bar 5, shell 0."},{"kind":"mcq","prompt":"What is the Mayan third landmark number?","options":["400","360","300","7200"],"answer":1,"explain":"20 × 18 = 360, possibly linked to their calendars."},{"kind":"numberline","prompt":"77 = (3) × 20 + (?) × 1. Tap it on the number line.","answer":17,"explain":"77 = 60 + 17.","min":0,"max":20,"step":1}]},{"id":"y2","title":"Carving Big Numbers","icon":"🛕","kind":"lesson","story":"The temple door needs three numbers carved correctly — one slip and the stone resets.","teach":[{"title":"Using the placeholder","body":"361 = (1)×360 + (0)×20 + (1)×1 — the empty 20s position gets the shell.","visual":"• / 🐚 / •"},{"title":"Why it matters","body":"Because it isn't a true base system, Mayan numerals lack the computational advantages of a base — yet their place value and zero placeholder were a major advance.","visual":"place value ✅ base ❌"}],"questions":[{"kind":"numeric","prompt":"100 = (5) × 20 + (?) × 1.","answer":0,"explain":"100 = 5×20 exactly, so the 1s place needs the shell (0)."},{"kind":"numeric","prompt":"721 = (2) × 360 + (0) × 20 + (?) × 1.","answer":1,"explain":"720 + 1 = 721."},{"kind":"mcq","prompt":"The Mayan civilisation made great progress between…","options":["3rd and 10th centuries CE","10th and 15th centuries BCE","1st and 2nd centuries BCE","16th century CE"],"answer":0,"explain":"The Mayan civilisation flourished between the 3rd and 10th centuries CE in Central America."}]},{"id":"y-boss","title":"The Mayan Guardian","icon":"🗿","kind":"boss","boss":{"name":"Mayan Guardian","taunt":"The temple opens only to one who reads the shell."},"story":"Stone eyes watch. Answer to escape the temple before the door closes.","teach":[],"questions":[{"kind":"mcq","prompt":"Read this numeral: 4 (in 360s), 11 (in 20s), 0 (in 1s).","options":["1660","1440","1680","1600"],"answer":0,"explain":"4×360 + 11×20 + 0 = 1440 + 220 = 1660."},{"kind":"mcq","prompt":"Why is the Mayan system NOT a true base-20 system?","options":["It has no zero","Its third landmark is 360, not 400","It counts downwards","It uses bars"],"answer":1,"explain":"A base-20 system would need 20² = 400 as the third landmark."},{"kind":"order","prompt":"Arrange the Mayan landmark numbers in increasing order.","items":["360","20","7200","1"],"answer":["1","20","360","7200"],"explain":"1, 20, 360, 7200, 144000."}]}]},{"id":"china","index":10,"name":"Chinese Kingdom","subtitle":"Rods that switch direction","emoji":"🏯","theme":"Cherry blossoms, pagodas, lanterns, bamboo","palette":{"from":"#f28482","to":"#9d0208","accent":"#5c0a0a"},"lessons":[{"id":"n1","title":"Rod Numerals","icon":"🎋","kind":"lesson","story":"Bamboo rods click on a counting board. Vertical, horizontal, vertical, horizontal…","teach":[{"title":"Two number systems","body":"The Chinese used a written system for recording and a rod-based system for computing. Rod numerals developed by at least the 3rd century AD and were used till the 17th century.","visual":"| || ||| |||| ⊤"},{"title":"Zongs and Hengs","body":"It is a decimal (base-10) place value system. Zongs (vertical) are used for units, hundreds, ten-thousands; hengs (horizontal) for tens, thousands, hundred-thousands.","visual":"zong | · heng —"},{"title":"Reading a numeral","body":"= (2 heng), ⊤ (6 zong), ≡ (3 heng), |||| (4 zong) = 2×10³ + 6×10² + 3×10 + 4 = 2634.","visual":"2634"}],"questions":[{"kind":"mcq","prompt":"The Chinese rod numeral system is base…","options":["5","10","20","60"],"answer":1,"explain":"Rod numerals are decimal — base-10."},{"kind":"mcq","prompt":"Why did the Chinese alternate zong and heng symbols?","options":["For decoration","So neighbouring place values can be told apart","Because rods were of two lengths","To mark zero"],"answer":1,"explain":"Alternating directions makes it easy to see where one position ends and the next begins."},{"kind":"numberline","prompt":"Read the rod numeral: 2 (thousands), 6 (hundreds), 3 (tens), 4 (ones). Tap it on the number line.","answer":2634,"explain":"2×1000 + 6×100 + 3×10 + 4 = 2634.","min":2629,"max":2639,"step":1}]},{"id":"n2","title":"The Missing Zero","icon":"🏮","kind":"lesson","story":"Light a lantern for every filled place — but what lights an empty one?","teach":[{"title":"Blank spaces again","body":"Like the Mesopotamians, rod numerals used a blank space to skip a place value. Because the symbols were of more uniform size, the blanks were easier to spot.","visual":"| _ ||| "},{"title":"So close","body":"Rod numerals are very similar to the Hindu system. With a symbol for zero, the Chinese system would be a fully developed place value system.","visual":"rods + 0 = complete"}],"questions":[{"kind":"mcq","prompt":"What single thing would have made rod numerals a fully developed place value system?","options":["More rods","A symbol for zero","A bigger base","Written names"],"answer":1,"explain":"With a symbol for zero, the Chinese system would be fully developed."},{"kind":"mcq","prompt":"If only zong symbols were used, 41 would look like ||||| — which could also be read as…","options":["5","14","410","9"],"answer":0,"explain":"Without alternation or spacing, four rods and one rod merge and can be read as 5."}]},{"id":"n-boss","title":"The Lantern Dragon","icon":"🐉","kind":"boss","boss":{"name":"Lantern Dragon","taunt":"Arrange my rods, or the festival stays dark!"},"story":"A paper dragon coils around the pagoda, guarding the last lantern.","teach":[],"questions":[{"kind":"order","prompt":"Order the place values of a rod numeral from rightmost to leftmost.","items":["10²","1","10³","10"],"answer":["1","10","10²","10³"],"explain":"The rightmost position holds the 1s, then 10s, 100s, 1000s."},{"kind":"mcq","prompt":"Rod numerals were used in China until about which century?","options":["3rd century","10th century","17th century","20th century"],"answer":2,"explain":"They developed by at least the 3rd century AD and were used till the 17th century."},{"kind":"numeric","prompt":"Write the number that is 3 thousands, 0 hundreds, 7 tens and 2 ones.","answer":3072,"explain":"3072 — the empty hundreds place is exactly where a zero is needed."}]}]},{"id":"zero","index":11,"name":"Kingdom of Zero","subtitle":"The invention that changed everything","emoji":"🪷","theme":"Golden palace, Indian architecture, stars, lotus","palette":{"from":"#ffd166","to":"#b5179e","accent":"#4a0d5c"},"lessons":[{"id":"z1","title":"The Hindu Number System","icon":"🔟","kind":"lesson","story":"Golden domes, lotus ponds — and ten small symbols that can write every number that ever was.","teach":[{"title":"Ten symbols","body":"Base-10, place value, ten digits 0–9. 375 = (3)×10² + (7)×10 + (5)×1. One digit in each position, so no ambiguity ever.","visual":"3 7 5"},{"title":"Written in India","body":"The way we write numbers originated in India around 2000 years ago. The first known use of ten digits including 0 (as a dot) is in the Bakhshali manuscript, c. 3rd century CE.","visual":"• = 0"},{"title":"Zero as a number","body":"Aryabhata (c. 499 CE) computed with the system in the Āryabhaṭīya. Brahmagupta codified 0 as a number in the Brāhmasphuṭasiddhānta (628 CE), creating what we now call a ring.","visual":"0 + a = a   ·   0 × a = 0"}],"questions":[{"kind":"mcq","prompt":"In which manuscript does the first known written 0 (as a dot) appear?","options":["Āryabhaṭīya","Bakhshali manuscript","Yajurveda Samhita","Brāhmasphuṭasiddhānta"],"answer":1,"explain":"The Bakhshali manuscript, c. 3rd century CE, shows zero as a dot."},{"kind":"mcq","prompt":"Who codified 0 as a number in 628 CE?","options":["Aryabhata","Brahmagupta","Al-Khwārizmī","Fibonacci"],"answer":1,"explain":"Brahmagupta, in the Brāhmasphuṭasiddhānta (628 CE)."},{"kind":"numberline","prompt":"375 = (3) × 10² + (?) × 10 + (5) × 1. Tap it on the number line.","answer":7,"explain":"The 7 sits in the tens place.","min":0,"max":10,"step":1}]},{"id":"z2","title":"Journey Across the World","icon":"🌏","kind":"lesson","story":"The numerals set sail: to the Arab world, then Europe, then everywhere.","teach":[{"title":"To the Arab world","body":"Transmitted by around 800 CE, popularised by Al-Khwārizmī (whose name gives us 'algorithm') in On the Calculation with Hindu Numerals (c. 825) and by Al-Kindi (c. 830).","visual":"800 CE ➜"},{"title":"To Europe","body":"Reached Europe and parts of Africa by around 1100 CE. Fibonacci argued for them around 1200, but Roman numerals were so ingrained that adoption took centuries — until the Renaissance.","visual":"1100 · 1200 · 1600s"},{"title":"The name","body":"Arab scholars called them Hindu numerals; Europeans called them Arabic numerals. Today: Hindu numerals, Indian numerals, or Hindu-Arabic numerals. 'Hindu' here means a geography and people, not a religion.","visual":"🇮🇳 → 🌍"}],"questions":[{"kind":"order","prompt":"Put the journey of the Hindu numerals in order.","items":["Fibonacci argues for them in Europe (c. 1200)","Developed in India (c. 2000 years ago)","Reach Europe & Africa (c. 1100 CE)","Transmitted to the Arab world (c. 800 CE)"],"answer":["Developed in India (c. 2000 years ago)","Transmitted to the Arab world (c. 800 CE)","Reach Europe & Africa (c. 1100 CE)","Fibonacci argues for them in Europe (c. 1200)"],"explain":"India → Arab world (800 CE) → Europe (1100 CE) → Fibonacci (1200)."},{"kind":"mcq","prompt":"The word 'algorithm' comes from the name of…","options":["Al-Kindi","Al-Khwārizmī","Aryabhata","Laplace"],"answer":1,"explain":"Al-Khwārizmī, the great Persian mathematician."},{"kind":"mcq","prompt":"Why were they called 'Arabic numerals' in Europe?","options":["They were invented in Arabia","European scholars learned them from the Arab world","Fibonacci named them so","They were written in Arabic script"],"answer":1,"explain":"It reflected the European perspective; Arab scholars themselves called them Hindu numerals."}]},{"id":"z3","title":"The Five Great Ideas","icon":"🌟","kind":"lesson","story":"Before the final battle, the Guardian must recite the whole evolution of number representation.","teach":[{"title":"The ladder of ideas","body":"1) Count in groups of a single number. 2) Group using landmark numbers. 3) Choose powers of a number as landmarks — a base. 4) Use positions for landmarks — place value. 5) Zero as a positional digit and as a number.","visual":"1 → 2 → 3 → 4 → 5"}],"questions":[{"kind":"order","prompt":"Arrange the five great ideas in the order they appear in the chapter.","items":["Place value: positions denote landmarks","Counting in groups of a single number","Zero as a digit and as a number","Landmark numbers (I V X L C M)","Base: landmarks are powers of a number"],"answer":["Counting in groups of a single number","Landmark numbers (I V X L C M)","Base: landmarks are powers of a number","Place value: positions denote landmarks","Zero as a digit and as a number"],"explain":"Groups → landmarks → base → place value → zero."},{"kind":"match","prompt":"Match each civilisation with its system.","pairs":[["Egypt","Base-10, no place value"],["Mesopotamia","Base-60 place value"],["Maya","Almost base-20, shell zero"],["China","Rod numerals, base-10"]],"explain":"Each contributed one step towards the modern system."},{"kind":"mcq","prompt":"Which system makes writing every number possible with only finitely many symbols?","options":["Egyptian","Roman","Hindu number system","Tally marks"],"answer":2,"explain":"Place value plus zero means ten digits suffice for every number."}]},{"id":"z-boss","title":"The Number Thief","icon":"👹","kind":"boss","boss":{"name":"The Number Thief","taunt":"I hold Zero itself. Without it, all your places collapse into confusion!"},"story":"The final battle. Recover Zero and restore the history of mathematics.","teach":[],"questions":[{"kind":"mcq","prompt":"Zero is indispensable in a place value system because it…","options":["Makes numbers bigger","Marks an empty position unambiguously","Replaces the base","Is the first landmark"],"answer":1,"explain":"Zero shows nothingness in a position, so numerals can be read one way only."},{"kind":"numeric","prompt":"Write 25 as a base-2 (binary) numeral.","answer":11001,"placeholder":"digits","explain":"25 = 16 + 8 + 1 → 11001."},{"kind":"numeric","prompt":"Write 25 as a base-5 numeral.","answer":100,"explain":"25 = 1×5² + 0×5 + 0 → 100."},{"kind":"mcq","prompt":"By introducing 0 with negative numbers, Brahmagupta created what modern mathematics calls a…","options":["Base","Ring","Numeral","Landmark"],"answer":1,"explain":"A ring: a set closed under addition, subtraction and multiplication."},{"kind":"order","prompt":"Final seal: order these number systems by the stage of the idea they represent.","items":["Roman numerals","Tally marks","Hindu number system","Egyptian numerals","Babylonian numerals"],"answer":["Tally marks","Roman numerals","Egyptian numerals","Babylonian numerals","Hindu number system"],"explain":"One-to-one → landmarks → base → place value → place value with zero."}]}]},{"id":"lockers","index":12,"name":"Locker Vault","subtitle":"Squares, Cubes & Their Roots","emoji":"🔐","theme":"Mysterious mansion, glowing lockers, brass keys","palette":{"from":"#ffd166","to":"#7209b7","accent":"#3a0866"},"lessons":[{"id":"sq1","title":"The 100 Lockers","icon":"🔑","kind":"lesson","story":"Queen Ratnamanjuri's puzzle: 100 people toggle 100 lockers. Person n toggles every nth locker. Which lockers stay open?","teach":[{"title":"Toggling by factors","body":"A locker is toggled once for every factor of its number. Locker 6 has factors 1,2,3,6 — toggled 4 times (even), so it ends closed.","visual":"6: 1,2,3,6"},{"title":"Squares are different","body":"Most factors pair up (1×6, 2×3) — except for perfect squares, where one factor pairs with itself (6×6=36). That gives squares an odd number of factors, so they stay open.","visual":"36 = 6×6"}],"questions":[{"kind":"mcq","prompt":"A locker stays open at the end only if its number is toggled an ______ number of times.","options":["even","odd","prime","zero"],"answer":1,"explain":"Squares have exactly one repeated factor pair, giving an odd factor count."},{"kind":"mcq","prompt":"Which of these locker numbers will remain OPEN?","options":["15","49","20","33"],"answer":1,"explain":"49 = 7×7 is a perfect square, so it has an odd number of factors (1, 7, 49)."},{"kind":"numeric","prompt":"How many factors does the number 9 have (1, 3, and 9)?","answer":3,"explain":"9 = 1×9 = 3×3, giving factors 1, 3, 9 — three factors, an odd count."}]},{"id":"sq2","title":"Digit Detective","icon":"🕵️","kind":"lesson","story":"Before checking every square by hand, learn the tricks that instantly rule numbers out.","teach":[{"title":"Last-digit rule","body":"Every perfect square ends in 0, 1, 4, 5, 6 or 9. If a number ends in 2, 3, 7 or 8, it can NEVER be a perfect square.","visual":"0 1 4 5 6 9 ✅ · 2 3 7 8 ❌"},{"title":"Sum of odd numbers","body":"Every perfect square is a sum of consecutive odd numbers starting at 1: 1=1², 1+3=2², 1+3+5=3², 1+3+5+7=4² …","visual":"1+3+5+7=16=4²"}],"questions":[{"kind":"mcq","prompt":"Which of these numbers can definitely NOT be a perfect square?","options":["256","3123","841","900"],"answer":1,"explain":"3123 ends in 3 — perfect squares never end in 2, 3, 7 or 8."},{"kind":"numberline","prompt":"What is 1+3+5+7+9? Tap it on the number line.","answer":25,"explain":"The sum of the first five odd numbers equals 5² = 25.","min":0,"max":30,"step":5},{"kind":"mcq","prompt":"If 35² = 1225, what is the 36th odd number you'd add to find 36²?","options":["70","71","72","36"],"answer":1,"explain":"The nth odd number is 2n−1, so the 36th odd number is 2×36−1 = 71."}]},{"id":"sq3","title":"Cube Quest","icon":"📦","kind":"lesson","story":"Beyond squares lie cubes — and a taxi ride that became mathematical legend.","teach":[{"title":"Perfect cubes","body":"A cube is n×n×n = n³. 1³=1, 2³=8, 3³=27, 4³=64, 5³=125 — the perfect cubes.","visual":"2³=8 · 3³=27"},{"title":"Cube roots by factorisation","body":"Group prime factors into triplets. 3375 = 3×3×3×5×5×5 = (3×5)³ = 15³, so the cube root of 3375 is 15.","visual":"3375 = 15³"},{"title":"The taxicab number","body":"Mathematician Ramanujan told Hardy that 1729 (a taxi's number) was special: it's the smallest number expressible as a sum of two cubes in two different ways — 1³+12³ and 9³+10³.","visual":"1729 = 1³+12³ = 9³+10³"}],"questions":[{"kind":"mcq","prompt":"What is the cube root of 3375, given 3375 = 3×3×3×5×5×5?","options":["10","15","25","45"],"answer":1,"explain":"Group into triplets (3×5)³=15³, so ∛3375 = 15."},{"kind":"numeric","prompt":"What is 6³ (6×6×6)?","answer":216,"explain":"6×6×6 = 216."},{"kind":"fill","prompt":"1729 is called the Hardy–______ number.","answer":"ramanujan","explain":"Named for the mathematician Srinivasa Ramanujan, who spotted its special property instantly."}]},{"id":"sq-boss","title":"The Locker Keeper","icon":"👹","kind":"boss","boss":{"name":"The Locker Keeper","taunt":"Every locker in this vault is sealed by a root. Crack them all!"},"story":"The vault's final door is sealed by three riddles of squares and cubes.","teach":[],"questions":[{"kind":"mcq","prompt":"Is 156 a perfect square? Its prime factorisation is 2×2×3×13.","options":["Yes","No — the factors 3 and 13 cannot be paired up","No — it has too few factors","Cannot be determined"],"answer":1,"explain":"156 = 2² × 3 × 13; 3 and 13 have no partner, so 156 is not a perfect square."},{"kind":"numeric","prompt":"What is the square root of 1936, given 44×44=1936?","answer":44,"explain":"√1936 = 44."},{"kind":"mcq","prompt":"500 = 2×2×5×5×5. Is 500 a perfect cube?","options":["Yes","No — the factors can't be split into three identical groups","Yes, because it ends in 0","No, because it's even"],"answer":1,"explain":"500's prime factors (2,2,5,5,5) can't form three equal triplet groups."},{"kind":"numeric","prompt":"What is 7² + 2³ (49 + 8)?","answer":57,"explain":"7²=49 and 2³=8, so 49+8=57."}]}]},{"id":"powerplay","index":13,"name":"Fold of Infinity","subtitle":"Exponents & The Power of Powers","emoji":"⚡","theme":"Origami folds, glowing grids, exponential towers","palette":{"from":"#22d3ee","to":"#7c3aed","accent":"#1e1065"},"lessons":[{"id":"p1","title":"The Impossible Fold","icon":"📄","kind":"lesson","story":"A sheet of paper 0.001 cm thick. Fold it, and fold it again. By fold 46, it would reach the Moon.","teach":[{"title":"Doubling with folds","body":"Each fold doubles the thickness. After a folds, the thickness is 0.001 × 2^a cm — this explosive growth is called exponential growth.","visual":"2¹ 2² 2³ 2⁴ …"},{"title":"Exponential notation","body":"n multiplied by itself a times is written nᵃ. Here n is the base and a is the exponent (or power). 2¹⁰ = 1024.","visual":"2¹⁰ = 1024"}],"questions":[{"kind":"mcq","prompt":"After 10 folds the paper's thickness increases by 1024 times. What is 1024 written as a power of 2?","options":["2⁸","2⁹","2¹⁰","2¹¹"],"answer":2,"explain":"2 multiplied by itself 10 times: 2¹⁰=1024."},{"kind":"numeric","prompt":"What is 3⁴ (3×3×3×3)?","answer":81,"explain":"3×3×3×3 = 81."},{"kind":"fill","prompt":"In the expression 5⁴, the number 5 is called the ______.","answer":"base","explain":"5 is the base; 4 is the exponent."}]},{"id":"p2","title":"Multiplying Powers","icon":"✖️","kind":"lesson","story":"A king's daughters, baskets, keys and rooms multiply by 3 at every step. How many rooms in total?","teach":[{"title":"Same base, multiply","body":"When multiplying powers with the same base, add the exponents: nᵃ × nᵇ = nᵃ⁺ᵇ. Example: 3⁴ × 3³ = 3⁷.","visual":"nᵃ × nᵇ = nᵃ⁺ᵇ"},{"title":"Power of a power","body":"Raising a power to another power multiplies the exponents: (nᵃ)ᵇ = nᵃˣᵇ. Example: (2²)⁵ = 2¹⁰.","visual":"(nᵃ)ᵇ = nᵃᵇ"},{"title":"Different base, same power","body":"When the exponents match but bases differ: mᵃ × nᵃ = (mn)ᵃ. Example: 2⁴ × 3⁴ = 6⁴.","visual":"mᵃ×nᵃ=(mn)ᵃ"}],"questions":[{"kind":"mcq","prompt":"p⁴ × p⁶ simplifies to:","options":["p¹⁰","p²⁴","p²","p¹"],"answer":0,"explain":"Same base, add exponents: 4+6=10."},{"kind":"numeric","prompt":"Simplify (4³)² and write it as a power of 4 — what is the exponent?","answer":6,"explain":"(4³)²=4^(3×2)=4⁶."},{"kind":"mcq","prompt":"2⁵ × 5⁵ can be rewritten as:","options":["7⁵","10⁵","10¹⁰","25⁵"],"answer":1,"explain":"Same exponent, multiply bases: 2×5=10, so 10⁵."}]},{"id":"p3","title":"Dividing & Zero Power","icon":"➗","kind":"lesson","story":"Halve a 16-unit line again and again. What happens when you've halved it exactly as many times as its power?","teach":[{"title":"Same base, subtract","body":"Dividing powers with the same base subtracts the exponents: nᵃ ÷ nᵇ = nᵃ⁻ᵇ. Example: 2⁴ ÷ 2³ = 2¹.","visual":"nᵃ÷nᵇ=nᵃ⁻ᵇ"},{"title":"Anything to the power 0","body":"Following the same rule, nᵃ ÷ nᵃ = nᵃ⁻ᵃ = n⁰ — but anything divided by itself is 1. So n⁰ = 1 for any n ≠ 0.","visual":"n⁰ = 1"}],"questions":[{"kind":"mcq","prompt":"2¹⁰⁰ ÷ 2²⁵ simplifies to:","options":["2⁴","2⁷⁵","2¹²⁵","2⁴⁰⁰⁰"],"answer":1,"explain":"Subtract exponents: 100-25=75."},{"kind":"numeric","prompt":"What is 7⁰?","answer":1,"explain":"Any nonzero number raised to the power 0 equals 1."},{"kind":"mcq","prompt":"Why is n⁰ defined as 1 (for n≠0)?","options":["It's just a convention with no reason","So the rule nᵃ÷nᵇ=nᵃ⁻ᵇ stays consistent even when a=b","Because 0 is a special number","Because n⁰ means 'no n's multiplied'"],"answer":1,"explain":"Defining n⁰=1 keeps the division rule consistent: nᵃ÷nᵃ=n⁰=1."}]},{"id":"p-boss","title":"The Combination Lock","icon":"🔒","kind":"boss","boss":{"name":"The Combination Lock","taunt":"Every one of my digits hides a power. Solve them all to unlock the vault!"},"story":"A vault door built from ten spinning digit wheels. Prove your mastery of powers to override it.","teach":[],"questions":[{"kind":"numeric","prompt":"How many different 3-digit passwords are possible if each digit can be 0-9?","answer":1000,"explain":"10×10×10 = 10³ = 1000."},{"kind":"mcq","prompt":"Which expression equals 10⁵?","options":["5¹⁰","10×5","100,000","10+10+10+10+10"],"answer":2,"explain":"10⁵ = 100,000."},{"kind":"mcq","prompt":"Simplify: (2³)² ÷ 2⁴","options":["2²","2⁴","2⁶","2¹⁰"],"answer":0,"explain":"(2³)²=2⁶, then 2⁶÷2⁴=2²."},{"kind":"numberline","prompt":"What is 2⁴ (2×2×2×2)? Tap it on the number line.","answer":16,"explain":"2×2×2×2=16.","min":0,"max":20,"step":2}]}]},{"id":"quadrilaterals","index":14,"name":"Carpenter's Workshop","subtitle":"Rectangles, Rhombuses & Quadrilaterals","emoji":"📐","theme":"Wood workshop, rulers, wooden frames, sawdust","palette":{"from":"#e07a5f","to":"#3d405b","accent":"#81b29a"},"lessons":[{"id":"q1","title":"The Carpenter's Rectangle","icon":"🔨","kind":"lesson","story":"A carpenter needs two wooden strips joined at their midpoints by a thread to form a perfect rectangle. What must be true about the strips?","teach":[{"title":"Angle sum of any quadrilateral","body":"Split any quadrilateral into two triangles with one diagonal. Since each triangle's angles sum to 180°, the quadrilateral's four angles always sum to 360°.","visual":"180°+180°=360°"},{"title":"Defining a rectangle","body":"A rectangle is a quadrilateral where all four angles are 90°. This alone guarantees opposite sides are equal and parallel — you don't need to state that separately!","visual":"90°+90°+90°+90°=360°"}],"questions":[{"kind":"numberline","prompt":"The angles of a quadrilateral are 100°, 80°, 95° and x°. What is x? Tap it on the number line.","answer":85,"explain":"360-100-80-95=85.","min":70,"max":100,"step":5},{"kind":"mcq","prompt":"Why can't a quadrilateral have exactly three right angles and a fourth angle that isn't 90°?","options":["It's not a rule, it's just rare","The four angles must sum to 360°, so the fourth angle is forced to be 90° too","Quadrilaterals can only have 2 right angles","Right angles must be opposite each other"],"answer":1,"explain":"90+90+90=270, leaving exactly 90° for the fourth angle."},{"kind":"mcq","prompt":"A rectangle can be defined simply as a quadrilateral where:","options":["Opposite sides are parallel","All four angles are 90°","One pair of sides is equal","Diagonals are perpendicular"],"answer":1,"explain":"This single condition forces opposite sides to be equal and parallel too."}]},{"id":"q2","title":"Diagonal Detective","icon":"🔍","kind":"lesson","story":"Two diagonals cross inside a quadrilateral. Depending on how, you get a rectangle, a rhombus, or a square.","teach":[{"title":"Rectangle diagonals","body":"A rectangle's diagonals are equal in length AND bisect each other (cross at their midpoints).","visual":"AC = BD, both bisected"},{"title":"Square diagonals","body":"A square is a rectangle with all sides equal. Its diagonals are equal, bisect each other, AND cross at exactly 90°.","visual":"90° crossing"},{"title":"Rhombus diagonals","body":"A rhombus has all four sides equal (but angles need not be 90°). Its diagonals bisect each other at 90° AND bisect the angles — but they aren't necessarily equal in length.","visual":"⊥ bisecting"}],"questions":[{"kind":"mcq","prompt":"Which shape's diagonals are always equal in length AND bisect each other?","options":["Rhombus","Rectangle","Trapezium","Kite"],"answer":1,"explain":"Equal + bisecting diagonals is the defining test for a rectangle."},{"kind":"mcq","prompt":"Which shape's diagonals cross at exactly 90° but are NOT necessarily equal in length?","options":["Rectangle","Square","Rhombus","None of these"],"answer":2,"explain":"A rhombus's diagonals are perpendicular bisectors of each other, but only a square (a special rhombus) also has equal diagonals."},{"kind":"fill","prompt":"A rhombus is a quadrilateral in which all ______ are of equal length.","answer":"sides","explain":"That's the defining property of a rhombus — unlike a rectangle, its angles need not be 90°."}]},{"id":"q3","title":"Rhombus, Kite & Trapezium","icon":"🪁","kind":"lesson","story":"Not every four-sided shape is a rectangle. Meet three more — each with its own personality.","teach":[{"title":"Rhombus angles","body":"In any rhombus, opposite angles are equal, and adjacent angles add up to 180°. Example: if one angle is 50°, the opposite angle is also 50°, and the two angles next to it are each 130°.","visual":"50°,130°,50°,130°"},{"title":"Kite","body":"A kite has two pairs of adjacent equal sides (AB=BC, CD=DA). The diagonal joining the vertices between the equal pairs (B and D) bisects the angles at B and D, and is the perpendicular bisector of the other diagonal.","visual":"AB=BC, CD=DA"},{"title":"Trapezium","body":"A trapezium has at least ONE pair of parallel sides. Where two sides are parallel, the angles on the same leg add up to 180° (co-interior angles).","visual":"∠S+∠P=180°"}],"questions":[{"kind":"numeric","prompt":"A rhombus has one angle of 70°. What is its opposite angle?","answer":70,"explain":"Opposite angles in a rhombus are always equal."},{"kind":"numeric","prompt":"A rhombus has one angle of 70°. What is one of its two adjacent angles?","answer":110,"explain":"Adjacent angles in a rhombus add up to 180°: 180-70=110."},{"kind":"mcq","prompt":"In a kite ABCD where AB=BC and CD=DA, which diagonal bisects the angles at B and D?","options":["AC","BD","Neither","Both"],"answer":1,"explain":"BD is the diagonal of symmetry — it bisects ∠ABC and ∠ADC, and is the perpendicular bisector of AC."}]},{"id":"q-boss","title":"The Master Carpenter","icon":"👷","kind":"boss","boss":{"name":"The Master Carpenter","taunt":"Every joint in my workshop must be exact. Prove you know every quadrilateral!"},"story":"The final challenge: identify every shape in the workshop by its properties alone.","teach":[],"questions":[{"kind":"mcq","prompt":"Which statement is true of EVERY square?","options":["It is a rhombus but never a rectangle","It is both a rectangle and a rhombus","It has no equal sides","Its diagonals are unequal"],"answer":1,"explain":"A square satisfies both the rectangle definition (all angles 90°) and the rhombus definition (all sides equal)."},{"kind":"numeric","prompt":"Three angles of a quadrilateral are 90°, 90°, and 90°. What must the fourth angle be?","answer":90,"explain":"360-90-90-90=90 — confirming three right angles force the fourth to be 90° too."},{"kind":"mcq","prompt":"A trapezium is defined as a quadrilateral with:","options":["All sides equal","At least one pair of parallel sides","All angles equal","Perpendicular diagonals"],"answer":1,"explain":"Just one pair of parallel sides is enough to qualify as a trapezium."},{"kind":"mcq","prompt":"Which of these is NOT necessarily true for a rhombus?","options":["All sides are equal","Diagonals bisect each other at 90°","All angles are 90°","Opposite angles are equal"],"answer":2,"explain":"A rhombus's angles need not be 90° — if they are, it's specifically a square."}]}]},{"id":"numberplay","index":15,"name":"Parity Puzzle Chamber","subtitle":"Multiples, Divisibility & Proof","emoji":"🎲","theme":"Puzzle room, gears, number tiles, chalk equations","palette":{"from":"#4cc9f0","to":"#3a0ca3","accent":"#240046"},"lessons":[{"id":"np1","title":"Odd, Even & Always True","icon":"➕","kind":"lesson","story":"Anshu plays with four consecutive numbers, placing + and − between them in every possible way. Every single result comes out even — always.","teach":[{"title":"Parity rules","body":"odd ± odd = even, even ± even = even, odd ± even = odd. Switching a sign in an expression always changes its value by an even number, so it never changes whether the total is odd or even.","visual":"odd±odd=even"},{"title":"Always / Sometimes / Never","body":"Mathematicians test claims by asking: is this Always True, Sometimes True, or Never True? Example: 'If 8 divides two numbers, it divides their sum' — Always True, since 8a+8b=8(a+b).","visual":"8a+8b=8(a+b)"}],"questions":[{"kind":"mcq","prompt":"3 – 4 – 5 – 6 and 3 + 4 + 5 + 6 both come from the same four consecutive numbers with signs changed. What do both results have in common?","options":["Both are odd","Both are even","Both are prime","Both are negative"],"answer":1,"explain":"Switching a sign always changes the value by an even amount, so the parity (odd/even) never changes."},{"kind":"mcq","prompt":"Is the statement 'If a number is divisible by 8, then any two numbers that add up to it are also divisible by 8' Always, Sometimes, or Never true?","options":["Always True","Sometimes True","Never True"],"answer":1,"explain":"E.g. 16=8+8 (both divisible by 8) but also 16=10+6 (neither divisible by 8) — so only sometimes."},{"kind":"numeric","prompt":"If M and N are both multiples of 7, is M+N always a multiple of 7? Enter 1 for yes, 0 for no.","answer":1,"explain":"M=7j, N=7k, so M+N=7(j+k) — always a multiple of 7."}]},{"id":"np2","title":"Multiples of Four","icon":"🔢","kind":"lesson","story":"Take any two even numbers and add them. Sometimes the sum is a multiple of 4 — sometimes it isn't. What decides it?","teach":[{"title":"Two kinds of even numbers","body":"Every even number leaves either remainder 0 or remainder 2 when divided by 4. Numbers like 4,8,12 leave remainder 0; numbers like 2,6,10 leave remainder 2.","visual":"4p (rem 0) · 4p+2 (rem 2)"},{"title":"Adding them up","body":"(4p)+(4q)=4(p+q) — multiple of 4. (4p+2)+(4q+2)=4(p+q+1) — also a multiple of 4! But (4p)+(4q+2)=4(p+q)+2 — NOT a multiple of 4.","visual":"0+0=mult4 · 2+2=mult4 · 0+2=not"}],"questions":[{"kind":"mcq","prompt":"Which pair of even numbers will NOT sum to a multiple of 4?","options":["4 and 8","6 and 10","4 and 6","2 and 6"],"answer":2,"explain":"4 leaves remainder 0, 6 leaves remainder 2 mod 4; 4+6=10, not a multiple of 4."},{"kind":"numberline","prompt":"12 and 20 are both multiples of 4. 12 + 20 = ? Tap where it lands on the number line.","min":0,"max":40,"step":4,"answer":32,"explain":"32÷4=8, confirming the sum of two multiples of 4 is itself a multiple of 4."},{"kind":"mcq","prompt":"6 and 10 both leave remainder 2 when divided by 4. What do you notice about 6+10=16?","options":["It's a multiple of 4","It's odd","It leaves remainder 2","It's prime"],"answer":0,"explain":"Two remainder-2 numbers add to give a remainder of 4, which wraps around to a full extra group of 4."}]},{"id":"np3","title":"The Digit-Sum Trick","icon":"🔟","kind":"lesson","story":"Without dividing at all, you can tell if a huge number is a multiple of 9 — just by adding its digits.","teach":[{"title":"Why it works","body":"Every place value is one more than a multiple of 9: 10=9+1, 100=99+1, 1000=999+1... So each digit's contribution to the remainder (mod 9) is just the digit itself.","visual":"10=9+1 · 100=99+1"},{"title":"The rule","body":"A number is divisible by 9 exactly when the sum of its digits is divisible by 9. Example: 7+3+0+9=19, and 19 is not divisible by 9, so 7309 is not divisible by 9 (remainder 1).","visual":"7309 → 7+3+0+9=19"}],"questions":[{"kind":"numeric","prompt":"What is the digit sum of 999?","answer":27,"explain":"9+9+9=27, and 27 is divisible by 9 — so 999 is divisible by 9."},{"kind":"mcq","prompt":"Is 522 divisible by 9? (5+2+2=9)","options":["Yes","No","Cannot tell","Only if it's even"],"answer":0,"explain":"Digit sum 9 is divisible by 9, so 522 is divisible by 9 (522÷9=58)."},{"kind":"numeric","prompt":"What is the remainder when 427 is divided by 9, using the digit-sum method (4+2+7=13, then 1+3)?","answer":4,"explain":"4+2+7=13, then 1+3=4 — matching the remainder found by direct division."}]},{"id":"np-boss","title":"The Proof Master","icon":"🧙","kind":"boss","boss":{"name":"The Proof Master","taunt":"Show me you can reason like a mathematician — always, sometimes, or never!"},"story":"The chamber's final gate opens only for those who can prove a pattern, not just guess it.","teach":[],"questions":[{"kind":"mcq","prompt":"If a divides M and a divides N, what can we always say about M−N?","options":["a divides M−N","a never divides M−N","M−N is always 0","Nothing can be said"],"answer":0,"explain":"M=ax, N=ay, so M−N=a(x−y) — always divisible by a."},{"kind":"numberline","prompt":"What is the digit sum of 8712? Tap it on the number line.","min":0,"max":30,"step":1,"answer":18,"explain":"8+7+1+2=18."},{"kind":"mcq","prompt":"Since 18 is divisible by 9, what can you conclude about 8712?","options":["It's divisible by 9","It's divisible by 2 only","It's prime","Nothing"],"answer":0,"explain":"By the digit-sum rule, 8712 is divisible by 9 (8712÷9=968)."},{"kind":"mcq","prompt":"'Switching one sign in a ± expression always changes its value by an even number.' This is:","options":["Always true","Sometimes true","Never true"],"answer":0,"explain":"Switching +b to −b changes the total by exactly 2b, which is always even."}]}]},{"id":"distribute","index":16,"name":"Identity Forge","subtitle":"Distributivity & Algebraic Identities","emoji":"🧮","theme":"Blacksmith forge, glowing equations, hammer and anvil","palette":{"from":"#f77f00","to":"#d62828","accent":"#7a1a1a"},"lessons":[{"id":"d1","title":"The Distributive Hammer","icon":"🔨","kind":"lesson","story":"23 × 27 — instead of multiplying directly, break 27 apart and distribute the multiplication.","teach":[{"title":"The core rule","body":"a(b+c) = ab + ac — the distributive property of multiplication over addition. It lets you break a hard multiplication into easier pieces.","visual":"a(b+c)=ab+ac"},{"title":"Growing a product","body":"If one number in a product increases by 1, the product increases by the OTHER number: a(b+1) = ab + a.","visual":"a(b+1)=ab+a"}],"questions":[{"kind":"mcq","prompt":"Using distributivity, 23 × (27+1) equals:","options":["23×27 + 1","23×27 + 23","23×27 + 27","23×28"],"answer":1,"explain":"a(b+1)=ab+a, so the product increases by a=23."},{"kind":"numberline","prompt":"Expand and simplify: 5(x+3) when x=4. What's the value? Tap it on the number line.","answer":35,"explain":"5(4+3)=5×7=35, matching 5x+15=5(4)+15=35.","min":0,"max":50,"step":5},{"kind":"mcq","prompt":"a(b+c) = ab+ac is called the:","options":["Commutative property","Associative property","Distributive property","Identity property"],"answer":2,"explain":"This is the distributive property of multiplication over addition."}]},{"id":"d2","title":"Squares of Sums","icon":"➕","kind":"lesson","story":"Forge a new identity: what happens when you square (a+b)?","teach":[{"title":"Identity: square of a sum","body":"(a+b)² = a² + 2ab + b². Example: (x+3)² = x² + 6x + 9.","visual":"(a+b)²=a²+2ab+b²"},{"title":"Identity: square of a difference","body":"(a-b)² = a² - 2ab + b². Example: (x-2)² = x² - 4x + 4.","visual":"(a-b)²=a²-2ab+b²"}],"questions":[{"kind":"mcq","prompt":"Expand (x+5)²:","options":["x²+25","x²+10x+25","x²+5x+25","x²+10x+10"],"answer":1,"explain":"(a+b)²=a²+2ab+b² with a=x,b=5: x²+10x+25."},{"kind":"numeric","prompt":"Use (a-b)²=a²-2ab+b² to find (10-2)² — what is 100-40+4?","answer":64,"explain":"(10-2)²=8²=64, matching 100-40+4=64."},{"kind":"fill","prompt":"(a+b)² = a² + ___ + b² — what is the middle term (in terms of a and b)?","answer":"2ab","explain":"The middle term is always twice the product of the two terms."}]},{"id":"d3","title":"The Difference of Squares","icon":"⚡","kind":"lesson","story":"9×9 − 1×1 = 10×8. 8×8 − 6×6 = 14×2. A hidden pattern connects every one of these.","teach":[{"title":"Identity: difference of squares","body":"a² - b² = (a+b)(a-b). This is why 9²-1² = (9+1)(9-1) = 10×8 = 80.","visual":"a²-b²=(a+b)(a-b)"},{"title":"Sridharacharya's shortcut","body":"The identity can be flipped to compute squares fast: a² = (a+b)(a-b)+b². To find 31², take b=1: 31²=(32)(30)+1=961.","visual":"31²=32×30+1=961"}],"questions":[{"kind":"mcq","prompt":"Using a²-b²=(a+b)(a-b), what is 98×102?","options":["9996","10000","9998","10004"],"answer":0,"explain":"98×102=(100-2)(100+2)=100²-2²=10000-4=9996."},{"kind":"numeric","prompt":"Using Sridharacharya's trick with a=29,b=1: 29²=(30)(28)+1. What is 30×28?","answer":840,"explain":"30×28=840, so 29²=840+1=841."},{"kind":"numeric","prompt":"What is 29² (from the previous question, 840+1)?","answer":841,"explain":"840+1=841, matching 29×29=841."}]},{"id":"d-boss","title":"The Forgemaster","icon":"👹","kind":"boss","boss":{"name":"The Forgemaster","taunt":"Every identity in this forge must be flawless. One mistake and the metal cracks!"},"story":"The forge's final test: spot the broken identity and forge the correct one.","teach":[],"questions":[{"kind":"mcq","prompt":"Spot the mistake: (5m+6n)² = 25m²+36n². What's missing?","options":["Nothing is wrong","The middle term 60mn","A constant term","Nothing — but the sign is wrong"],"answer":1,"explain":"(a+b)²=a²+2ab+b² — the middle term 2×5m×6n=60mn was dropped."},{"kind":"numeric","prompt":"What is 6²-2² (using a²-b²)?","answer":32,"explain":"6²-2²=36-4=32, matching (6+2)(6-2)=8×4=32."},{"kind":"mcq","prompt":"Which expression correctly expands (x-4)²?","options":["x²-16","x²-8x+16","x²-4x+16","x²+16"],"answer":1,"explain":"(a-b)²=a²-2ab+b²: x²-8x+16."},{"kind":"numeric","prompt":"What is 10² - 6²?","answer":64,"explain":"100-36=64, and also (10+6)(10-6)=16×4=64 — confirming the identity."}]}]},{"id":"proportional1","index":17,"name":"The Similarity Lab","subtitle":"Ratios & Proportional Reasoning","emoji":"🖼️","theme":"Photo lab, resizing frames, measuring tapes","palette":{"from":"#06b6d4","to":"#0891b2","accent":"#164e63"},"lessons":[{"id":"pr1","title":"Which Images Match?","icon":"🖼️","kind":"lesson","story":"Five resized tiger photos. Three look right, two look stretched or squashed. What's the mathematical difference?","teach":[{"title":"Same factor, same shape","body":"Image A (60×40mm) resized to C (30×20mm): both width AND height were multiplied by the same factor, ½. That's why they still look alike — they are proportional.","visual":"60:40 × ½ = 30:20"},{"title":"Different factor, distorted","body":"Image B (40×20mm) came from A by SUBTRACTING 20mm from both — not the same MULTIPLYING factor. Subtracting the same amount does NOT preserve proportion, so B looks stretched.","visual":"60-20=40, 40-20=20 (not proportional!)"}],"questions":[{"kind":"mcq","prompt":"Two rectangles are proportional (look similar) when their width and height:","options":["Differ by the same amount","Change by the same multiplying factor","Are both even numbers","Add up to the same total"],"answer":1,"explain":"Proportional change means multiplying both dimensions by the same factor."},{"kind":"mcq","prompt":"A 60×40mm image is resized by multiplying both sides by 1.5. What are the new dimensions?","options":["90×60","61.5×41.5","90×55","61×41"],"answer":0,"explain":"60×1.5=90, 40×1.5=60 — both scaled by the same factor."},{"kind":"fill","prompt":"The ratio of width to height is written using which symbol between the two numbers?","answer":":","explain":"A ratio a:b is read 'a to b'."}]},{"id":"pr2","title":"Simplest Form & Sweet Lemonade","icon":"🍋","kind":"lesson","story":"Kesang made 6 glasses of lemonade with 10 spoons of sugar. Her father wants 18 more glasses — same sweetness. How much sugar?","teach":[{"title":"Simplest form","body":"Divide both terms of a ratio by their HCF to get its simplest form. 60:40, HCF=20, simplest form 3:2.","visual":"60:40 ÷20 = 3:2"},{"title":"Solving a proportion","body":"6:10 :: 18:? — the first term grew by a factor of 18÷6=3, so the second term must grow by the same factor: 10×3=30.","visual":"6:10::18:30"}],"questions":[{"kind":"numeric","prompt":"What is the HCF of 72 and 96?","answer":24,"explain":"72=24×3, 96=24×4 — 24 is their highest common factor."},{"kind":"mcq","prompt":"72:96 in simplest form is:","options":["3:4","2:3","4:5","1:2"],"answer":0,"explain":"Dividing both terms by their HCF, 24: 72÷24=3, 96÷24=4."},{"kind":"numberline","prompt":"Solve: 6:10 :: 18:? — what is the missing number? Tap it on the number line.","answer":30,"explain":"The scale factor is 18÷6=3, so 10×3=30.","min":0,"max":50,"step":5}]},{"id":"pr3","title":"The Wall-Building Trap","icon":"🧱","kind":"lesson","story":"Nitin built a 60ft wall with 3 bags of cement. Hari built a 40ft wall with 2 bags. Nitin worries Hari's wall is weaker — is he right?","teach":[{"title":"Compare the ratios","body":"Nitin: 60:3 = 20:1 (simplest form). Hari: 40:2 = 20:1 (simplest form). Since both simplify to the same ratio, they used cement equally efficiently.","visual":"60:3=20:1, 40:2=20:1"},{"title":"A trap: addition breaks proportion","body":"When Neelima was 3, her mother was 30 (ratio 1:10). Nine years later, Neelima is 12 and her mother is 39 — ratio 12:39 = 4:13, NOT 1:10! Adding the same number to both terms does not preserve a ratio.","visual":"3:30 ≠ 12:39 (after +9 each)"}],"questions":[{"kind":"mcq","prompt":"Nitin's wall ratio is 60:3 and Hari's is 40:2. Are they proportional?","options":["Yes — both simplify to 20:1","No — 60≠40","No — 3≠2","Cannot be determined"],"answer":0,"explain":"Both ratios reduce to 20:1, so Hari used cement just as efficiently as Nitin."},{"kind":"mcq","prompt":"If you add the SAME number to both terms of a ratio, the new ratio is:","options":["Always still proportional to the original","Not necessarily proportional to the original","Always simpler","Always equal to the original"],"answer":1,"explain":"Only multiplying (or dividing) both terms by the same factor preserves proportionality — adding does not."},{"kind":"numeric","prompt":"A ratio 14:21 needs to become ?:42. Since 42=21×2, what should the first term become (14×2)?","answer":28,"explain":"To stay proportional, multiply BOTH terms by the same factor: 14×2=28."}]},{"id":"pr-boss","title":"The Proportion Inspector","icon":"🕵️","kind":"boss","boss":{"name":"The Proportion Inspector","taunt":"Every ratio in this lab must check out. Prove they're truly proportional!"},"story":"The lab's final inspection: verify or fix every ratio before the exhibit opens.","teach":[],"questions":[{"kind":"mcq","prompt":"Are the ratios 3:4 and 72:96 proportional?","options":["Yes — both simplify to 3:4","No","Cannot tell without more info","Only if multiplied by 2"],"answer":0,"explain":"72:96 simplifies (÷24) to 3:4, matching the first ratio exactly."},{"kind":"numeric","prompt":"A recipe ratio is 6:10 (glasses:spoons). For 30 glasses, how many spoons are needed?","answer":50,"explain":"Scale factor 30÷6=5, so 10×5=50 spoons."},{"kind":"mcq","prompt":"5 teachers to 170 students simplifies (÷5) to:","options":["1:34","1:17","5:34","1:170"],"answer":0,"explain":"170÷5=34, 5÷5=1, giving 1:34."},{"kind":"mcq","prompt":"Which action always preserves a ratio's proportionality?","options":["Adding a constant to both terms","Subtracting a constant from both terms","Multiplying both terms by the same factor","Multiplying just one term"],"answer":2,"explain":"Only multiplying (or dividing) both terms by the same non-zero factor keeps a ratio proportional."}]}]},{"id":"percentages","index":18,"name":"The Percentage Market","subtitle":"Fractions in Disguise","emoji":"💯","theme":"Bustling marketplace, price tags, sale banners","palette":{"from":"#f72585","to":"#7209b7","accent":"#3a0068"},"lessons":[{"id":"pc1","title":"Per Hundred","icon":"💯","kind":"lesson","story":"'Mega Sale — up to 50% off!' What does that tiny % symbol actually mean?","teach":[{"title":"Per cent = out of 100","body":"Per cent comes from Latin 'per centum' — 'out of a hundred'. A percentage is just a fraction with denominator 100: 25% = 25/100.","visual":"25% = 25/100"},{"title":"Converting a fraction to a percentage","body":"Multiply the fraction by 100. 3/4 × 100 = 75, so 3/4 = 75%.","visual":"3/4 × 100 = 75%"}],"questions":[{"kind":"mcq","prompt":"What does 40% mean?","options":["40 out of 1000","40 out of 100","4 out of 10,000","40 out of 40"],"answer":1,"explain":"Per cent means 'per hundred' — 40% = 40/100."},{"kind":"numberline","prompt":"Express 2/5 as a percentage — what number goes before the % sign? Tap it on the number line.","answer":40,"explain":"2/5 × 100 = 40, so 2/5 = 40%.","min":0,"max":100,"step":10},{"kind":"numeric","prompt":"25 out of a class of 40 students are girls. What percentage is that? (25/40 × 100)","answer":62.5,"explain":"25/40 = 0.625, ×100 = 62.5%."}]},{"id":"pc2","title":"Fraction ⇄ Percentage","icon":"🔄","kind":"lesson","story":"A biscuit factory needs to know instantly: is Variety 1 (sugar = 9/34) or Variety 2 (sugar = 13/45) sweeter?","teach":[{"title":"Why 100 wins","body":"Comparing 9/34 and 13/45 directly is hard. Converting both to percentages (≈26.47% and ≈28.88%) makes the comparison instant — that's the whole point of percentages.","visual":"9/34≈26.5% vs 13/45≈28.9%"},{"title":"Percentage to fraction","body":"To reverse it, write z% as z/100 and simplify. 24% = 24/100 = 6/25.","visual":"24% = 6/25"}],"questions":[{"kind":"mcq","prompt":"24% expressed as a fraction in simplest form is:","options":["24/100","12/50","6/25","3/12.5"],"answer":2,"explain":"24/100 simplifies by dividing both terms by 4: 6/25."},{"kind":"mcq","prompt":"Which is larger: 3/11 or 61%?","options":["3/11","61%","They are equal","Cannot compare"],"answer":1,"explain":"3/11 ≈ 27.3%, which is far less than 61%."},{"kind":"numeric","prompt":"Nandini has 25 marbles, 15 of which are white. What percentage are white? (15/25×100)","answer":60,"explain":"15/25 = 0.6, ×100 = 60%."}]},{"id":"pc3","title":"Profit, Loss & Discount","icon":"🏷️","kind":"lesson","story":"Kishanlal buys sweaters at ₹300 and sells them at ₹430 after haggling. Did he do well?","teach":[{"title":"Profit/Loss percentage","body":"Profit % = (Profit ÷ Cost Price) × 100. Kishanlal's profit: ₹430−₹300=₹130. Profit% = 130/300×100 ≈ 43.3%.","visual":"profit% = profit/CP × 100"},{"title":"Discount","body":"A discount reduces the marked price. A '35% discount' on an MRP of ₹1800 means the customer pays only 65% of ₹1800.","visual":"100%-35%=65% of MP"}],"questions":[{"kind":"numeric","prompt":"Raghu bought rice at ₹35/kg (₹350 for 10kg) and sold all 10kg for ₹300. What is the loss in rupees?","answer":50,"explain":"₹350-₹300=₹50 loss."},{"kind":"numeric","prompt":"Using the ₹50 loss on a ₹350 cost, what is the loss percentage (50/350×100), rounded to nearest whole number?","answer":14,"explain":"50/350×100≈14.3%, which rounds to 14%."},{"kind":"mcq","prompt":"A cooker has MRP ₹1800 with a 35% discount. What percentage of the MRP does the customer actually pay?","options":["35%","65%","135%","100%"],"answer":1,"explain":"100%-35% discount = 65% of the marked price is paid."}]},{"id":"pc-boss","title":"The Market Auditor","icon":"🧾","kind":"boss","boss":{"name":"The Market Auditor","taunt":"Every price tag in this market must check out perfectly. Prove your percentages!"},"story":"The market's books need auditing before closing time. Get every calculation right.","teach":[],"questions":[{"kind":"numeric","prompt":"Shyamala bought a vase for ₹2650 and sells it at an 18% loss. What percentage of ₹2650 does she actually get (100-18)?","answer":82,"explain":"18% loss means she receives 82% of the cost price."},{"kind":"numeric","prompt":"82% of ₹2650 is how much (rounded to nearest rupee)? (0.82×2650)","answer":2173,"explain":"0.82×2650=2173."},{"kind":"mcq","prompt":"5/11 as a percentage is approximately:","options":["45.5%","55%","20%","11%"],"answer":0,"explain":"5÷11≈0.4545, ×100≈45.5%."},{"kind":"mcq","prompt":"Which correctly finds profit percentage?","options":["(Selling Price ÷ Cost Price) × 100","(Profit ÷ Cost Price) × 100","(Profit ÷ Selling Price) × 100","Profit × 100"],"answer":1,"explain":"Profit percentage is always calculated with respect to the Cost Price."}]}]},{"id":"pythagoras","index":19,"name":"The Diagonal Temple","subtitle":"The Baudhāyana–Pythagoras Theorem","emoji":"📐","theme":"Ancient altar, sacred geometry, sand diagrams","palette":{"from":"#fca311","to":"#14213d","accent":"#000814"},"lessons":[{"id":"py1","title":"Doubling the Square","icon":"◆","kind":"lesson","story":"Around 800 BCE, Baudhāyana posed a puzzle: how do you build a square with EXACTLY double the area of a given one?","teach":[{"title":"Not by doubling the side","body":"Doubling a square's side multiplies its area by 4, not 2 (2×2=4). That's too much.","visual":"side×2 → area×4"},{"title":"The diagonal trick","body":"Baudhāyana's answer: build a NEW square on the DIAGONAL of the original square. That new square has exactly double the area.","visual":"diagonal → 2× area"}],"questions":[{"kind":"mcq","prompt":"If you double a square's side length, its area becomes:","options":["2 times as large","4 times as large","Half as large","The same"],"answer":1,"explain":"Area scales with the square of the side, so doubling the side quadruples the area."},{"kind":"mcq","prompt":"Baudhāyana showed a square with double the area of the original can be built on the original square's:","options":["Side","Diagonal","Corner","Perimeter"],"answer":1,"explain":"A square built on the diagonal has exactly twice the area of the original."},{"kind":"mcq","prompt":"A unit square (area 1) is made of 2 small triangles. The doubled square (built on its diagonal) is made of how many of those same triangles?","options":["2","3","4","8"],"answer":2,"explain":"The doubled square contains 4 of the small congruent triangles — twice the original's 2."}]},{"id":"py2","title":"The Number √2","icon":"➗","kind":"lesson","story":"A right triangle with two legs of length 1. What's the length of its slanted third side?","teach":[{"title":"Finding the hypotenuse","body":"A unit right-angle triangle's square-on-hypotenuse has area 2 (double the unit square). Since area = side², the hypotenuse c satisfies c²=2, so c=√2.","visual":"c²=2 → c=√2"},{"title":"√2 is irrational","body":"√2 cannot be written as a terminating decimal or as a fraction m/n. Its decimal goes on forever without repeating: 1.41421356… This makes √2 an irrational number.","visual":"√2 = 1.41421356…"}],"questions":[{"kind":"numeric","prompt":"A right triangle has two legs each of length 1 unit. What is the square of its hypotenuse (1²+1²)?","answer":2,"explain":"By the theorem, c²=1²+1²=2."},{"kind":"mcq","prompt":"√2 is called an irrational number because:","options":["It's a negative number","It cannot be written as a terminating decimal or as a fraction m/n","It's larger than 2","It has no decimal value"],"answer":1,"explain":"Its decimal expansion never terminates or repeats, and it can't be expressed as a ratio of integers."},{"kind":"mcq","prompt":"Which two whole numbers is √2 trapped between?","options":["0 and 1","1 and 2","2 and 3","3 and 4"],"answer":1,"explain":"1²=1<2 and 2²=4>2, so 1<√2<2."}]},{"id":"py3","title":"The Sacred Theorem","icon":"📏","kind":"lesson","story":"In his Śulba-Sūtra, Baudhāyana stated the rule that would later be called the Pythagorean theorem — centuries before Pythagoras.","teach":[{"title":"The theorem","body":"For any right triangle with legs a, b and hypotenuse c: a²+b²=c². Baudhāyana stated this in full generality, and Pythagoras (c.500 BCE) studied it independently centuries later.","visual":"a²+b²=c²"},{"title":"A worked example","body":"A right triangle with legs 3cm and 4cm: 3²+4²=9+16=25=5². So the hypotenuse is 5cm — the famous 3-4-5 triangle.","visual":"3²+4²=5² → 9+16=25"},{"title":"Baudhāyana triples","body":"Whole-number triples (a,b,c) satisfying a²+b²=c² are called Baudhāyana (or Pythagorean) triples: (3,4,5), (5,12,13), (8,15,17), (7,24,25).","visual":"(3,4,5)(5,12,13)(8,15,17)"}],"questions":[{"kind":"numeric","prompt":"A right triangle has legs 5cm and 12cm. What is c² (5²+12²)?","answer":169,"explain":"25+144=169."},{"kind":"numberline","prompt":"From the previous question, c²=169. What is the hypotenuse c? Tap it on the number line.","answer":13,"explain":"√169=13, matching the famous (5,12,13) triple.","min":0,"max":20,"step":1},{"kind":"mcq","prompt":"A right triangle has a leg of 8cm and hypotenuse 17cm. What is the other leg?","options":["9cm","15cm","12cm","20cm"],"answer":1,"explain":"8²+b²=17² → 64+b²=289 → b²=225 → b=15, matching the (8,15,17) triple."}]},{"id":"py-boss","title":"The Temple Guardian","icon":"🗿","kind":"boss","boss":{"name":"The Temple Guardian","taunt":"Only those who master the sacred right-triangle rule may pass!"},"story":"The temple's final sand diagram is missing one measurement. Complete it to earn passage.","teach":[],"questions":[{"kind":"numeric","prompt":"A right triangle has legs 7cm and 24cm. What is c² (7²+24²)?","answer":625,"explain":"49+576=625."},{"kind":"numeric","prompt":"From c²=625, what is the hypotenuse c?","answer":25,"explain":"√625=25 — the (7,24,25) Baudhāyana triple."},{"kind":"mcq","prompt":"Which set of three numbers is a Baudhāyana (Pythagorean) triple?","options":["(2,3,4)","(6,8,10)","(5,6,7)","(9,10,11)"],"answer":1,"explain":"6²+8²=36+64=100=10² ✓. This is just the (3,4,5) triple doubled."},{"kind":"mcq","prompt":"Why couldn't the ancient mathematicians find a terminating decimal equal to √2?","options":["They didn't try hard enough","√2 is irrational — no terminating decimal or fraction equals it exactly","They lacked calculators","√2 doesn't really exist"],"answer":1,"explain":"√2's irrationality means no finite decimal or fraction can ever equal it exactly — proven by Euclid using prime factorisation."}]}]},{"id":"proportional2","index":20,"name":"The Map & Mixture Room","subtitle":"Proportional Reasoning — Part 2","emoji":"🗺️","theme":"Cartographer's table, spice jars, paint pots","palette":{"from":"#588157","to":"#3a5a40","accent":"#344e41"},"lessons":[{"id":"pr4","title":"Reading a Map's Scale","icon":"🗺️","kind":"lesson","story":"Every map hides a tiny ratio in its corner: RF 1:60,00,000. What does it actually tell you?","teach":[{"title":"Representative Fraction","body":"A map's RF (Representative Fraction) compares a distance ON the map to the real distance ON THE GROUND. RF 1:60,00,000 means 1cm on the map = 60,00,000cm in reality.","visual":"1cm map = 6,000,000cm real"},{"title":"Converting to km","body":"60,00,000 cm = 60,000 m = 60 km. So 1cm on this map represents 60km on the ground.","visual":"6,000,000cm = 60km"},{"title":"Cross-multiplication test","body":"Two ratios a:b and c:d are proportional exactly when a×d = b×c. Example: 6:3 and 4:2 — 6×2=12 and 3×4=12, so they ARE proportional.","visual":"a×d = b×c"}],"questions":[{"kind":"numeric","prompt":"A map's scale is 1:60,00,000. If two cities are 3cm apart on the map, how many km apart are they in reality? (3×60)","answer":180,"explain":"Each cm = 60km, so 3cm = 3×60=180km."},{"kind":"mcq","prompt":"Are the ratios 6:3 and 4:2 proportional?","options":["Yes — 6×2=12 equals 3×4=12","No — 6≠4","No — 3≠2","Cannot be determined"],"answer":0,"explain":"Cross-multiplying: 6×2=12 and 3×4=12 — they match, so the ratios are proportional."},{"kind":"mcq","prompt":"60,00,000 cm equals how many kilometres?","options":["6 km","60 km","600 km","6000 km"],"answer":1,"explain":"1km = 100,000cm, so 6,000,000cm ÷ 100,000 = 60km."}]},{"id":"pr5","title":"Spice Mix & Multi-Term Ratios","icon":"🌶️","kind":"lesson","story":"Viswanath's spice mix uses coriander, chillies, toor dal and fenugreek in ratio 8:4:2:1. Puneet only has 2 chillies — how much of everything else?","teach":[{"title":"Ratios with many terms","body":"A ratio can compare more than 2 quantities at once: 8:4:2:1. To stay proportional, EVERY term must be scaled by the same factor.","visual":"8:4:2:1"},{"title":"Scaling down","body":"Puneet has 2 chillies — half of Viswanath's 4. So every other ingredient is also halved: 4:2:1:0.5.","visual":"÷2 → 4:2:1:0.5"}],"questions":[{"kind":"numeric","prompt":"A spice mix uses coriander:chilli:dal:fenugreek = 8:4:2:1. If someone uses only 1 chilli (a quarter of 4), how many spoons of coriander should they use (8÷4)?","answer":2,"explain":"Scaling factor is ¼, so coriander becomes 8÷4=2."},{"kind":"mcq","prompt":"Purple paint needs Red:Blue:White = 2:3:5. With 10 litres of white (5 parts), how much is 1 part?","options":["1 litre","2 litres","5 litres","10 litres"],"answer":1,"explain":"White=5 parts=10 litres, so 1 part = 10÷5 = 2 litres."},{"kind":"numeric","prompt":"Using the previous answer (1 part = 2 litres), how many litres of red paint (2 parts) are needed?","answer":4,"explain":"Red = 2 parts × 2 litres = 4 litres."}]},{"id":"pr6","title":"Dividing the Whole","icon":"🥧","kind":"lesson","story":"110 units of concrete are needed, mixed as cement:sand:gravel = 1:1.5:3. How much of each?","teach":[{"title":"The formula","body":"To divide a total x in ratio a:b:c, each share is x × (its term) ÷ (sum of all terms). Total parts = 1+1.5+3 = 5.5.","visual":"share = x × term ÷ sum"},{"title":"Worked example","body":"110 ÷ 5.5 = 20 (the multiplying factor). Cement = 1×20=20, Sand = 1.5×20=30, Gravel = 3×20=60. Check: 20+30+60=110.","visual":"20+30+60=110"},{"title":"Triangle angles in a ratio","body":"The three angles of a triangle always sum to 180°. If they're in ratio 1:3:5 (total 9 parts), each part = 180÷9=20°, giving angles 20°, 60°, 100°.","visual":"1:3:5 of 180° = 20°,60°,100°"}],"questions":[{"kind":"numeric","prompt":"Divide 50ml of purple paint in the ratio Red:Blue:White = 2:3:5 (10 parts total). How much is Red (50×2/10)?","answer":10,"explain":"50 × 2/10 = 10ml."},{"kind":"numeric","prompt":"From the same mix (2:3:5, 10 parts, 50ml total), how much White paint (50×5/10)?","answer":25,"explain":"50 × 5/10 = 25ml."},{"kind":"numberline","prompt":"A triangle's angles are in ratio 1:3:5 (9 parts of 180°). What is the largest angle (180×5/9)? Tap it on the number line.","answer":100,"explain":"180 × 5/9 = 100°.","min":0,"max":180,"step":20}]},{"id":"pr-boss2","title":"The Master Cartographer","icon":"🧭","kind":"boss","boss":{"name":"The Master Cartographer","taunt":"Scale, mix and divide correctly, or your map will lead travellers astray!"},"story":"The final map must be scaled perfectly and its legend's ink mixed in exact proportion.","teach":[],"questions":[{"kind":"numeric","prompt":"A library has Odiya:Hindi:English books in ratio 3:2:1. If there are 288 Odiya books (3 parts), how many books is 1 part (288÷3)?","answer":96,"explain":"288÷3=96 books per part."},{"kind":"numeric","prompt":"Using 1 part=96 books, how many Hindi books (2 parts)?","answer":192,"explain":"96×2=192 Hindi books."},{"kind":"mcq","prompt":"100 coins are split ₹10:₹5:₹2:₹1 coins in ratio 4:3:2:1 (10 parts). How many ₹10 coins (100×4/10)?","options":["10","20","40","4"],"answer":2,"explain":"100 × 4/10 = 40 coins of ₹10."},{"kind":"mcq","prompt":"A map has RF 1:50,000. A road measuring 4cm on the map is how many metres in reality? (4×50,000cm)","options":["200m","2000m","20,000m","2m"],"answer":1,"explain":"4×50,000=200,000cm=2000m."}]}]},{"id":"geomthemes","index":21,"name":"The Fractal Gallery","subtitle":"Fractals & Visualising Solids","emoji":"🌀","theme":"Infinite mirror gallery, geometric art, shadow projectors","palette":{"from":"#9d4edd","to":"#5a189a","accent":"#240046"},"lessons":[{"id":"gt1","title":"Patterns Within Patterns","icon":"🌿","kind":"lesson","story":"A fern's leaf looks like a tiny fern. Its sub-leaves look like tiny leaves. This endless self-similarity has a name: fractal.","teach":[{"title":"What is a fractal","body":"A fractal is a shape that repeats the same pattern at smaller and smaller scales — self-similarity. Ferns, trees, coastlines, clouds and lightning are all natural fractals.","visual":"🌿 → leaf → leaflet → …"},{"title":"Sierpinski Carpet","body":"Start with a square, split it into 9 smaller squares, remove the centre one, then repeat on each remaining square forever. At step n, the number of remaining squares is 8ⁿ.","visual":"Rₙ = 8ⁿ"}],"questions":[{"kind":"mcq","prompt":"A fractal is a shape that:","options":["Has straight sides only","Repeats a similar pattern at smaller and smaller scales","Can never be drawn","Only exists in nature"],"answer":1,"explain":"Self-similarity across scales is the defining feature of a fractal."},{"kind":"numberline","prompt":"In the Sierpinski Carpet, the number of remaining squares at step n is 8ⁿ. How many remain at step 2 (8²)? Tap it on the number line.","answer":64,"explain":"8²=64.","min":0,"max":96,"step":8},{"kind":"mcq","prompt":"Which of these is NOT mentioned as a natural example of a fractal?","options":["Ferns","Coastlines","Lightning","Perfect circles"],"answer":3,"explain":"Ferns, trees, coastlines, clouds and lightning show natural fractal patterns; perfect circles do not."}]},{"id":"gt2","title":"Triangles, Snowflakes & Temples","icon":"❄️","kind":"lesson","story":"Two more fractals: a triangle that keeps losing its middle, and a snowflake that keeps growing bumps.","teach":[{"title":"Sierpinski Triangle","body":"Join the midpoints of an equilateral triangle to split it into 4 smaller identical triangles, remove the middle one, then repeat on the remaining 3 — forever.","visual":"△→▲▲▲ (middle removed)"},{"title":"Koch Snowflake","body":"Divide each side of a triangle into 3 parts, raise a smaller triangle on the middle part (a 'bump'), and repeat on every new side. Described by Von Koch in 1904.","visual":"─ → bump shape"},{"title":"Fractals in human art","body":"The Kandariya Mahadev Temple in Khajuraho (c. 1025 CE) shows a large tower made of smaller copies of itself, with even smaller copies on those — a fractal built centuries before the word existed.","visual":"🛕 self-similar tower"}],"questions":[{"kind":"mcq","prompt":"The Sierpinski Triangle is made by repeatedly removing the ______ triangle.","options":["Largest","Middle","Smallest","Corner"],"answer":1,"explain":"Each equilateral triangle is split into 4, and the central one is removed, over and over."},{"kind":"mcq","prompt":"The Koch Snowflake was first described by:","options":["Sierpinski","Von Koch","Escher","Pythagoras"],"answer":1,"explain":"Swedish mathematician Von Koch first described it in 1904."},{"kind":"fill","prompt":"The Kandariya Mahadev Temple, an example of fractal-like art, is located in ______.","answer":"khajuraho","explain":"Khajuraho, Madhya Pradesh, completed around 1025 CE."}]},{"id":"gt3","title":"Views of a Solid","icon":"📦","kind":"lesson","story":"A cube looks like a square from the front, a square from the top, and a square from the side — but a cone tells a very different story from each angle.","teach":[{"title":"Three views","body":"Any solid can be described by its Front View, Top View, and Side View — the outline you'd see looking at it from each direction.","visual":"front · top · side"},{"title":"Shadows are projections","body":"When light shines perpendicular to a wall from very far away (like sunlight), the shadow cast is essentially the same as the object's projection onto that plane.","visual":"☀️ → shadow = projection"}],"questions":[{"kind":"mcq","prompt":"The three standard views used to describe a solid are:","options":["Big, medium, small","Front, top, side","Left, right, centre","North, south, east"],"answer":1,"explain":"Front View, Top View, and Side View together describe a 3D solid's shape."},{"kind":"mcq","prompt":"A cylinder standing upright shows which shape from its Top View?","options":["Rectangle","Circle","Triangle","Square"],"answer":1,"explain":"Looking straight down at a cylinder, you see its circular base."},{"kind":"mcq","prompt":"Why does a shadow from very distant, perpendicular sunlight closely match an object's projection?","options":["Because the sun is very bright","Because the light rays become nearly parallel over the great distance","Because shadows are always the same size as the object","It doesn't — they're unrelated"],"answer":1,"explain":"Very distant light rays travel almost parallel to each other, matching a true geometric projection."}]},{"id":"gt-boss","title":"The Pattern Keeper","icon":"🔮","kind":"boss","boss":{"name":"The Pattern Keeper","taunt":"Only those who see the pattern within the pattern may leave this gallery!"},"story":"The gallery's final mirror shows an infinite reflection. Answer to step through.","teach":[],"questions":[{"kind":"numeric","prompt":"In the Sierpinski Carpet, Rₙ=8ⁿ. How many squares remain at step 3 (8³)?","answer":512,"explain":"8³=512."},{"kind":"mcq","prompt":"A cube resting flat shows what shape in ALL three views (front, top, side)?","options":["Circle","Triangle","Square","Rectangle"],"answer":2,"explain":"A cube's outline is a square from every one of the three standard views."},{"kind":"mcq","prompt":"Which artist's 'Smaller and Smaller' print shows the same lizard pattern shrinking again and again?","options":["Von Koch","Sierpinski","M.C. Escher","Baudhāyana"],"answer":2,"explain":"The Dutch artist M.C. Escher created this famous fractal-inspired print."},{"kind":"mcq","prompt":"A fractal shape is best described as one that is:","options":["Random and unpredictable","Self-similar across different scales","Only found in mathematics textbooks","Always a perfect circle"],"answer":1,"explain":"Self-similarity — the same pattern recurring at smaller and smaller scales — defines a fractal."}]}]},{"id":"dotsandlines","index":22,"name":"The Balance Point","subtitle":"Mean, Median & Data Stories","emoji":"⚖️","theme":"Wrestling arena, coconut farm, scale balances","palette":{"from":"#ffb703","to":"#fb8500","accent":"#023047"},"lessons":[{"id":"dl1","title":"The Mean is a Balance Point","icon":"⚖️","kind":"lesson","story":"Mark the mean of a set of dots on a number line. Something surprising happens: the total distance is always balanced on both sides.","teach":[{"title":"Mean as balance","body":"The mean isn't just 'sum ÷ count' — it's the exact point where the total distance to values below equals the total distance to values above. That's why it's called a measure of the 'centre'.","visual":"distances balance ⚖️"},{"title":"Only one centre","body":"There is only ONE value where the distances balance. Move away from the true mean in either direction, and the balance breaks.","visual":"one unique balance point"}],"questions":[{"kind":"numberline","prompt":"What is the mean of 3 and 7? Tap it on the number line.","answer":5,"explain":"(3+7)/2=5, exactly halfway between them.","min":0,"max":10,"step":1},{"kind":"mcq","prompt":"The mean of a data set is best described as:","options":["Always the middle value when sorted","The point where total distances below and above are equal","Always the largest value","The most frequent value"],"answer":1,"explain":"That's the balance-point definition of the mean — different from the median!"},{"kind":"mcq","prompt":"If you add a new data value that is GREATER than the current mean, the mean will:","options":["Increase","Decrease","Stay exactly the same","Become the median"],"answer":0,"explain":"Adding a larger-than-average value pulls the balance point upward."}]},{"id":"dl2","title":"Shifting and Scaling","icon":"➕","kind":"lesson","story":"Coach Balwan's wrestlers' weights all increase by 10kg after a training season. What happens to the average?","teach":[{"title":"Adding a constant","body":"If you add the same fixed number to EVERY value in a data set, the mean increases by that same number. Add 10 to every weight → mean increases by 10.","visual":"mean+10 when every value+10"},{"title":"Multiplying by a constant","body":"If you multiply EVERY value by the same number, the mean is multiplied by that number too. Double every value → the mean doubles.","visual":"mean×5 when every value×5"}],"questions":[{"kind":"numeric","prompt":"A data set has mean 20. If 5 is added to every value, what is the new mean?","answer":25,"explain":"Adding a constant to every value shifts the mean by that same constant."},{"kind":"numeric","prompt":"A data set has mean 8. If every value is doubled, what is the new mean?","answer":16,"explain":"Multiplying every value by a constant multiplies the mean by the same constant."},{"kind":"mcq","prompt":"A data set has mean 12. If every value is multiplied by 3, what is the new mean?","options":["15","36","4","12"],"answer":1,"explain":"12×3=36."}]},{"id":"dl3","title":"Finding the Missing Weight","icon":"🔍","kind":"lesson","story":"Coach Balwan's notebook is smudged — one wrestler's weight is missing. But the average is known. Can you recover it?","teach":[{"title":"Working backwards from the mean","body":"Mean = (sum of all values) ÷ (count). If you know the mean and count, you can find the total sum, then subtract the known values to find the missing one.","visual":"sum = mean × count"},{"title":"Worked example","body":"10 wrestlers, mean weight 39.2kg → total = 39.2×10=392kg. Nine known weights sum to 349kg. Missing weight = 392−349 = 43kg.","visual":"392−349=43"},{"title":"Median shifts too","body":"Adding a value greater than the current median can shift the median upward — e.g. if the two middle values become 8 and 11, the new median is their average, 9.5.","visual":"median(8,11)=9.5"}],"questions":[{"kind":"numeric","prompt":"10 players have a mean weight of 39.2kg. What is their total combined weight (39.2×10)?","answer":392,"explain":"sum = mean × count = 39.2×10=392."},{"kind":"numeric","prompt":"Total weight is 392kg, and 9 known players weigh 349kg together. What is the missing player's weight?","answer":43,"explain":"392−349=43kg."},{"kind":"numeric","prompt":"15 trees average 25.6 coconuts each. What is the total harvest (25.6×15)?","answer":384,"explain":"25.6×15=384 coconuts total."}]},{"id":"dl-boss","title":"The Data Detective","icon":"🕵️","kind":"boss","boss":{"name":"The Data Detective","taunt":"Every number in this ledger must add up. Prove your skill with means and medians!"},"story":"The farm's records are in disarray. Solve each mystery to restore the ledger.","teach":[],"questions":[{"kind":"numeric","prompt":"Venkayya's total harvest was recorded as 384, but one tree's count was 3 too high. What is the corrected total (384-3)?","answer":381,"explain":"384-3=381 is the true total."},{"kind":"numeric","prompt":"The corrected total is 381 coconuts across 15 trees. What is the corrected average (381÷15)?","answer":25.4,"explain":"381÷15=25.4."},{"kind":"mcq","prompt":"If every value in a data set is reduced by 2, what happens to the mean?","options":["It increases by 2","It decreases by 2","It stays the same","It is halved"],"answer":1,"explain":"Subtracting a constant from every value decreases the mean by that same constant."},{"kind":"mcq","prompt":"Which statement about the median is TRUE?","options":["Adding any new value never changes the median","Adding a value greater than the median can increase the median","The median is always equal to the mean","The median ignores half the data entirely"],"answer":1,"explain":"A new value larger than the current median can shift which values are 'in the middle', increasing the median."}]}]},{"id":"algebraplay","index":23,"name":"The Trickster's Tent","subtitle":"Number Tricks & Puzzles","emoji":"🎩","theme":"Magic show tent, playing cards, number pyramids","palette":{"from":"#e63946","to":"#1d3557","accent":"#0b1d33"},"lessons":[{"id":"ap1","title":"Think of a Number","icon":"🔮","kind":"lesson","story":"Think of ANY number. Double it. Add four. Divide by two. Subtract your original number. The answer is always 2 — how?","teach":[{"title":"Following the trick with algebra","body":"Call your number x. Double: 2x. Add 4: 2x+4. Divide by 2: x+2. Subtract x: x+2−x=2. The x always cancels out — that's why the answer never changes!","visual":"x→2x→2x+4→x+2→2"},{"title":"Designing your own trick","body":"You can invent tricks that always land on any number you like, just by choosing the steps so the letter-number (x) cancels out at the end.","visual":"design: make x vanish"}],"questions":[{"kind":"mcq","prompt":"In the trick 'double it, add 4, divide by 2, subtract the original number', why does the answer always come out the same?","options":["It's a coincidence","The letter-number x always cancels out in the algebra","The trick only works for even numbers","It doesn't always work"],"answer":1,"explain":"x+2−x=2 — the x cancels regardless of what number you started with."},{"kind":"numeric","prompt":"Follow the trick with x=7: double it (14), add 4 (18), divide by 2 (9), subtract the original (9-7). What's the result?","answer":2,"explain":"No matter the starting number, this trick always ends at 2."},{"kind":"mcq","prompt":"A magician wants a trick that always ends in 5 instead of 2. What should they change?","options":["Nothing — it's impossible","Add a different number in step 3 (e.g. add 10 instead of 4)","Use a different starting number each time","Skip a step"],"answer":1,"explain":"Changing the added constant shifts the final fixed result — e.g. adding 10 instead of 4 would end at 5."}]},{"id":"ap2","title":"The Date-Guessing Trick","icon":"📅","kind":"lesson","story":"Multiply your birth month by 5, add 6, multiply by 4, add 9, multiply by 5, add your birth day. Tell me the answer — I'll name your exact date.","teach":[{"title":"Decoding the trick","body":"Let month=M, day=D. Following all the steps: 5M→+6→×4→+9→×5→+D gives 100M+165+D. Subtracting 165 from the final answer leaves 100M+D — a number where the LAST TWO digits are the day and the rest is the month!","visual":"answer−165 = 100M+D"},{"title":"Worked example","body":"If the final answer is 291: 291−165=126. The last two digits (26) are the day, and what's left (1) is the month — so the date is 26th January.","visual":"126 → month 1, day 26"}],"questions":[{"kind":"numeric","prompt":"Mukta's final answer was 1390. What do you get after subtracting 165 (1390-165)?","answer":1225,"explain":"1390-165=1225."},{"kind":"mcq","prompt":"1225 splits into month and day as 100M+D. What date does this represent?","options":["1st December","12th February","25th December","1st January"],"answer":2,"explain":"1225 = 100×12+25, so month=12, day=25 — 25th December."},{"kind":"numeric","prompt":"If the final answer of this trick is 296, subtract 165. What do you get?","answer":131,"explain":"296-165=131, meaning month 1, day 31 — 31st January."}]},{"id":"ap3","title":"Number Pyramids","icon":"🔺","kind":"lesson","story":"In a number pyramid, each brick equals the sum of the two bricks beneath it. Given just a few numbers, can you rebuild the whole pyramid?","teach":[{"title":"The building rule","body":"Every number is the sum of the two numbers directly below it. Going the other way (top to bottom), you can also SUBTRACT to find missing bottom bricks.","visual":"top = left+right"},{"title":"Using algebra to solve gaps","body":"When the bottom row has gaps too, label the unknowns with letters and write equations. Example: a+b=60, 12+c=a, c+8=b. Substituting gives 20+2c=60, so c=20.","visual":"20+2c=60 → c=20"}],"questions":[{"kind":"balance","prompt":"In a pyramid, the bottom row has 4 and 1. Balance the scale to find the box above.","leftLabel":"4 + 1","rightLabel":"the box above","options":[6,3,5,4],"answer":2,"explain":"Each box equals the sum of the two boxes beneath it: 4+1=5."},{"kind":"balance","prompt":"A pyramid's top is 10, and its bottom-left is 4. Balance the scale to find the missing bottom-right.","leftLabel":"4 + c","rightLabel":"10","options":[14,6,8,4],"answer":1,"explain":"Since top=left+right, right=10-left=10-4=6."},{"kind":"balance","prompt":"Balance the scale: 20 + 2c = 60. What is c?","leftLabel":"20 + 2c","rightLabel":"60","options":[40,10,20,15],"answer":2,"explain":"2c=60-20=40, so c=40/2=20."}]},{"id":"ap-boss","title":"The Master Magician","icon":"🎩","kind":"boss","boss":{"name":"The Master Magician","taunt":"Every trick has an algebraic secret. Reveal them all to win the show!"},"story":"The final act: reverse-engineer the magician's last three tricks.","teach":[],"questions":[{"kind":"mcq","prompt":"A 'think of a number' trick: triple it, add 6, divide by 3, subtract the original number. Algebra: (3x+6)/3 - x = ?","options":["x","2","3","6"],"answer":1,"explain":"(3x+6)/3 = x+2, then x+2-x=2 — always 2, regardless of x."},{"kind":"numeric","prompt":"A date-trick's final answer is 880. Subtract 165. What do you get (880-165)?","answer":715,"explain":"880-165=715, meaning month 7, day 15 — 15th July."},{"kind":"mcq","prompt":"From 715, what date does this represent?","options":["7th January","15th July","71st May","5th July"],"answer":1,"explain":"715 = 100×7+15, so month=7 (July), day=15."},{"kind":"balance","prompt":"A pyramid has top=45, bottom-left=20. Balance the scale to find the missing bottom-right.","leftLabel":"20 + c","rightLabel":"45","options":[15,65,25,20],"answer":2,"explain":"right = top - left = 45-20=25."}]}]},{"id":"area","index":24,"name":"The Rangoli Courtyard","subtitle":"Area of Rectangles & Triangles","emoji":"🎨","theme":"Rangoli patterns, courtyard tiles, coloured powder","palette":{"from":"#ff6b6b","to":"#f8961e","accent":"#6a040f"},"lessons":[{"id":"ar1","title":"Counting Unit Squares","icon":"🟦","kind":"lesson","story":"Two rectangular rangoli patches need colouring. Which one needs more powder?","teach":[{"title":"Area = length × width","body":"Area counts how many 1cm×1cm unit squares fit inside a shape. For a rectangle, that's simply length × width.","visual":"Area = l × w"},{"title":"Perimeter ≠ Area","body":"Two shapes can have the SAME perimeter but very DIFFERENT areas — perimeter tells you nothing reliable about area, so you can't use it as a substitute.","visual":"same perimeter ≠ same area"}],"questions":[{"kind":"numberline","prompt":"A rectangle is 7cm by 4cm. What is its area (in sq cm)? Tap it on the number line.","answer":28,"explain":"Area = length × width = 7×4=28.","min":0,"max":40,"step":4},{"kind":"mcq","prompt":"Which rectangle covers more area: 7cm×4cm, or 8cm×3cm?","options":["7×4 (28 sq cm)","8×3 (24 sq cm)","They're equal","Cannot tell"],"answer":0,"explain":"7×4=28 sq cm is greater than 8×3=24 sq cm."},{"kind":"mcq","prompt":"Can two shapes have the same perimeter but different areas?","options":["No, never","Yes, definitely","Only for squares","Only for triangles"],"answer":1,"explain":"Perimeter and area measure different things — a shape can be 'long and thin' with a big perimeter but small area, or vice versa."}]},{"id":"ar2","title":"Half the Rectangle","icon":"🔺","kind":"lesson","story":"A rectangle's diagonal always splits it into two identical triangles. What does that tell you about a triangle's area?","teach":[{"title":"The triangle formula","body":"Area of a triangle = ½ × base × height. This works because any triangle can be related to a rectangle with the same base and height — the triangle covers exactly half of it.","visual":"Area = ½ × base × height"},{"title":"Same base and height = same area","body":"In a rectangle, drawing both diagonals creates 4 triangles. Even though they look different, all 4 have EQUAL area — because each pair shares the same base and height.","visual":"4 triangles, equal area"}],"questions":[{"kind":"numeric","prompt":"A triangle has base 7cm and height 4cm. What is its area (½×7×4)?","answer":14,"explain":"½×7×4=14 sq cm."},{"kind":"mcq","prompt":"The area formula for a triangle works for EVERY triangle, including ones where the height falls outside the triangle, because:","options":["It only works for right triangles","The area can be found as the difference of two right-triangle areas that both use the same base×height logic","Triangles never have area","It's just an approximation"],"answer":1,"explain":"Even obtuse triangles can be handled by subtracting two right-triangle areas — the formula still holds exactly."},{"kind":"mcq","prompt":"A line from a triangle's vertex to the MIDPOINT of the opposite side divides it into:","options":["Two triangles of equal area","Two congruent triangles always","A rectangle","Two triangles of unequal area"],"answer":0,"explain":"Since both halves share the same height and equal base lengths, they always have equal area — even though they aren't always congruent in shape."}]},{"id":"ar3","title":"Solving for the Unknown","icon":"🧩","kind":"lesson","story":"The SAME triangle can have its area computed two different ways — using two different base-height pairs. That gives you a way to solve for a missing length.","teach":[{"title":"Two ways, one area","body":"A triangle's area doesn't change no matter which side you call the 'base'. If Area = ½×AX×BC = ½×BY×AC, you can set these equal to solve for an unknown length.","visual":"½×AX×BC = ½×BY×AC"},{"title":"Worked example","body":"A triangle with area 24 sq cm and base 8cm has height (2×24)/8=6cm. Using a different side of length 6cm as base instead, the height becomes (2×24)/6=8cm — same triangle, same area.","visual":"24 = ½×8×6 = ½×6×8"}],"questions":[{"kind":"numeric","prompt":"A triangle has area 24 sq cm. Using base=8cm, what is the height (2×24÷8)?","answer":6,"explain":"Area=½×base×height, so height=(2×24)/8=6cm."},{"kind":"numeric","prompt":"The same triangle (area 24 sq cm) has another side of length 6cm as its base. What is the corresponding height (2×24÷6)?","answer":8,"explain":"height=(2×24)/6=8cm — same triangle, same area, different base-height pair."},{"kind":"mcq","prompt":"Why can a triangle have different 'base and height' pairs that all give the same area?","options":["It can't — this is a mistake","The area is a fixed property of the triangle; changing which side you call the base just changes the corresponding height to compensate","Only right triangles allow this","The formula is only approximate"],"answer":1,"explain":"Area is fixed; base and height are just one way to describe it, and they trade off to keep the product (and hence area) constant."}]},{"id":"ar-boss","title":"The Rangoli Master","icon":"🕉️","kind":"boss","boss":{"name":"The Rangoli Master","taunt":"Every petal of this rangoli must be measured exactly. Prove your mastery of area!"},"story":"The final, most intricate rangoli pattern awaits — colour it correctly by computing every area.","teach":[],"questions":[{"kind":"numeric","prompt":"A rectangular plot (park+path) measures 24m×14m. What is its total area (24×14)?","answer":336,"explain":"24×14=336 sq m."},{"kind":"numeric","prompt":"The inner park inside is 20m×10m. What is the park's area?","answer":200,"explain":"20×10=200 sq m."},{"kind":"numeric","prompt":"What is the area of the path alone (336-200)?","answer":136,"explain":"Path area = whole plot area − inner park area = 336−200=136 sq m."},{"kind":"mcq","prompt":"A triangle has base 10cm and height 6cm. What is its area?","options":["60 sq cm","30 sq cm","16 sq cm","120 sq cm"],"answer":1,"explain":"Area=½×10×6=30 sq cm."}]}]}];